var DICT={"fr":{"idx.meta.title":"Numerocoon — Numérologie & horoscope de bien-être","idx.meta.desc":"Numerocoon, par Bengacoon : votre thème numérologique détaillé, votre ascendant calculé depuis l'heure de naissance, horoscope, compatibilité et guidance. Gratuit, en 9 langues.","brand.by":"par Bengacoon","nav.home":"Accueil","nav.features":"Fonctions","nav.guide":"Guide","nav.privacy":"Confidentialité","idx.hero.lead":"Numérologie & horoscope réunis. À partir de votre date, votre heure et votre lieu de naissance, découvrez votre thème, votre ascendant et une guidance qui vous ressemble.","idx.store.android":"<small>Android · APK direct</small>Télécharger","idx.store.play":"<small>Bientôt sur</small>Google&nbsp;Play","idx.store.ios":"<small>Bientôt sur</small>App&nbsp;Store","idx.func.eyebrow":"Ce que fait l'app","idx.func.h2":"Un portrait complet, en douceur","idx.func.sub":"Comprendre vos nombres, lire votre ciel et avancer jour après jour — sans compte, sans jargon.","idx.card.numero.h3":"Numérologie détaillée","idx.card.numero.p":"Chemin de vie, expression, âme, personnalité, défis et cycles, grille d'inclusion et dettes karmiques. Jusqu'à la part d'ombre de chaque nombre, pour un portrait honnête.","idx.card.ascendant.h3":"Ascendant & horoscope","idx.card.ascendant.p":"Votre signe solaire et votre ascendant, calculé astronomiquement depuis l'heure et le lieu de naissance. Horoscope du jour, de la semaine et jours favorables.","idx.card.synthese.h3":"Synthèse","idx.card.synthese.p":"Une lecture qui relie tout : Soleil × Ascendant × chemin de vie, et la combinaison de vos éléments dominants — feu, terre, air, eau.","idx.card.compat.h3":"Compatibilité détaillée","idx.card.compat.p":"Enregistrez vos proches et comparez vos thèmes sur 8 dimensions notées — amour, passion, amitié, communication, travail, valeurs, quotidien, stabilité — avec forces et points de vigilance.","idx.card.guidance.h3":"Guidance & journal","idx.card.guidance.p":"Un questionnaire de vie, puis une guidance personnalisée domaine par domaine selon votre année personnelle. Un journal pour noter la résonance de vos journées.","idx.card.rappel.h3":"Rappel & partage","idx.card.rappel.p":"Un rappel quotidien à l'heure de votre choix pour ne rien manquer, et le partage de votre journée en un geste, quand vous le souhaitez.","idx.free.price":"100 % gratuit","idx.free.h2":"Tout est offert, sans publicité","idx.free.sub":"Aucun achat, aucun abonnement, aucune fonction verrouillée.","idx.free.li1":"Thème numérologique complet","idx.free.li2":"Ascendant, horoscope et jours favorables","idx.free.li3":"Synthèse, compatibilité et guidance","idx.free.li4":"Journal, rappels et partage","idx.free.note":"Numerocoon est un cadeau de la galaxie Bengacoon — à découvrir en toute liberté.","idx.lang.eyebrow":"Pour tout le monde","idx.lang.h2":"Disponible en 9 langues","idx.lang.sub":"L'application est entièrement traduite, jusqu'aux textes de guidance.","idx.ver.eyebrow":"Toujours en mouvement","idx.ver.h2":"Les dernières versions","idx.ver.sub":"Numerocoon évolue régulièrement — voici les nouveautés récentes. L'historique complet est sur GitHub.","idx.ver.v1.label":"Fiche animale","idx.ver.v1.desc":"La fiche d'un animal est bien plus complète : forces, besoins, place dans la famille, mot doux et énergie du jour.","idx.ver.v2.label":"Icône & guide","idx.ver.v2.desc":"Nouvelle icône (médaillon d'or, croissant de lune) et un guide d'utilisation complet intégré, accessible hors ligne.","idx.ver.v3.label":"Fiches & photos","idx.ver.v3.desc":"Une photo sur chaque profil, la fiche complète d'une personne (signe, ascendant, nombres) et la fiche numérologique des animaux.","idx.ver.v4.label":"Profils & animaux","idx.ver.v4.desc":"Gérez plusieurs profils (conjoint, enfants, famille…) avec ajout/édition/suppression et liste de compatibilité, plus des profils pour vos animaux.","idx.ver.v5.label":"Calendrier & ciel","idx.ver.v5.desc":"Calendrier numérologique du mois, « ciel du moment » (Lune, Mercure rétrograde, nombre universel) et numérologie de votre animal de compagnie.","idx.ver.v6.label":"Widget d'accueil","idx.ver.v6.desc":"Un widget Android pour poser votre nombre du jour directement sur l'écran d'accueil de votre téléphone.","idx.ver.v7.label":"Carte, roue & prévisions","idx.ver.v7.desc":"Carte du jour à partager, roue du thème (Soleil + Ascendant), prévisions sur 12 mois, tendances du journal, sauvegarde/restauration, taille du texte réglable et tour de bienvenue.","idx.ver.v8.label":"MAJ directes","idx.ver.v8.desc":"La version APK direct télécharge et installe désormais ses mises à jour depuis l'application, sans passer par le navigateur.","idx.ver.v9.label":"Biorythmes & PDF","idx.ver.v9.desc":"Biorythmes du jour (physique, émotionnel, intellectuel), rubrique « Découvrir » pour tout comprendre, et export du thème complet en PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Alignement des versions iOS et Android et préparation de la publication sur les deux plateformes.","idx.ver.v11.label":"Réglages &amp; marque","idx.ver.v11.desc":"Roue crantée d'accès aux Réglages et signature « par Bengacoon » sur l'accueil.","idx.ver.v12.label":"100 % traduit","idx.ver.v12.desc":"Localisation complète, jusqu'aux phrases assemblées, dans les 9 langues.","idx.ver.more":"Voir tout l'historique des versions →","idx.priv.eyebrow":"Vos données, chez vous","idx.priv.h2":"Rien ne quitte votre téléphone","idx.priv.sub":"Aucun compte à créer, aucune donnée personnelle collectée. Votre profil et vos proches restent sur votre appareil. La seule connexion sert à vérifier les mises à jour — sans rien envoyer vous concernant.","idx.footer":"<strong>Numerocoon</strong> — par Bengacoon · Disponible en 9 langues<br>\n    <a href=\"guide.html\">Guide d'utilisation</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Politique de confidentialité</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon propose un support d'introspection et de bien-être fondé sur des traditions symboliques (numérologie, astrologie). Ce n'est ni une prédiction, ni un dispositif médical, ni un avis financier ou juridique, et cela ne remplace pas l'avis d'un professionnel qualifié.</p>","g.meta.title":"Guide d'utilisation — Numerocoon","g.meta.desc":"Le guide complet de Numerocoon : tout ce que vous pouvez faire (numérologie, ascendant, horoscope, compatibilité, profils, biorythmes…) et comment.","g.hero.h1":"Guide d'utilisation","g.hero.p":"Tout ce que vous pouvez faire avec Numerocoon, et comment. L'application est en 9 langues ; ce guide est en français.","g.toc.title":"Sommaire","g.toc.1":"1. Démarrer","g.toc.2":"2. Numérologie","g.toc.3":"3. Astrologie","g.toc.4":"4. Synthèse","g.toc.5":"5. Mes profils","g.toc.6":"6. Compatibilité","g.toc.7":"7. Animaux","g.toc.8":"8. Biorythmes","g.toc.9":"9. Prévisions & calendrier","g.toc.10":"10. Le ciel du moment","g.toc.11":"11. Guidance & journal","g.toc.12":"12. Carte & partage","g.toc.13":"13. Rapport PDF","g.toc.14":"14. Outils","g.toc.15":"15. Découvrir","g.toc.16":"16. Widget","g.toc.17":"17. Réglages","g.toc.18":"18. Mises à jour","g.toc.19":"19. Confidentialité","g.intro.note":"Chaque rubrique indique <strong style=\"color:var(--amethyste)\">où la trouver</strong> dans l'application (onglet en bas, roue des Réglages en haut à droite, ou tuiles d'accès rapide de l'accueil).","g.demarrer.h2":"1. Démarrer — créer votre profil","g.demarrer.ou":"À la première ouverture","g.demarrer.p1":"Au lancement, Numerocoon vous demande de créer votre profil. Renseignez :","g.demarrer.li1":"<strong>Prénom</strong> (obligatoire), nom et e-mail facultatifs ;","g.demarrer.li2":"<strong>Date de naissance</strong> (jour, mois, année) ;","g.demarrer.li3":"<strong>Heure de naissance</strong> et <strong>lieu</strong> — nécessaires pour calculer votre <em>ascendant</em> (facultatifs, mais recommandés).","g.demarrer.astuce":"🔒 Tout reste sur votre appareil : aucun compte en ligne, aucune donnée envoyée. Un tour de bienvenue vous présente l'app au premier lancement.","g.num.h2":"2. Numérologie","g.num.ou":"Onglet « Numérologie »","g.num.p1":"Votre thème numérologique pythagoricien complet :","g.num.li1":"<strong>Chemin de vie</strong> : votre nombre principal, avec son portrait (forces, défis, en amour, au travail, conseil).","g.num.li2":"<strong>Part d'ombre</strong> : la face cachée de votre nombre et son affirmation.","g.num.li3":"<strong>Nombres du nom</strong> : expression, âme, personnalité, actif, héréditaire, nombre de naissance.","g.num.li4":"<strong>Grille d'inclusion</strong> : vos atouts et vos leçons d'après votre nom.","g.num.li5":"<strong>Dettes karmiques</strong> (13, 14, 16, 19), <strong>défis</strong> et <strong>cycles de vie</strong>.","g.num.li6":"<strong>Année personnelle</strong> : le thème de votre année en cours.","g.astro.h2":"3. Astrologie & horoscope","g.astro.ou":"Onglet « Horoscope »","g.astro.li1":"<strong>Signe solaire</strong> et <strong>ascendant</strong> (calculé astronomiquement depuis votre heure et lieu de naissance).","g.astro.li2":"<strong>Horoscope du jour</strong> et de la <strong>semaine</strong>, par domaines.","g.astro.li3":"<strong>Jours favorables</strong> du mois.","g.astro.li4":"<strong>Compatibilité</strong> rapide entre signes.","g.astro.p1":"Pour la <strong>roue de votre thème</strong> (vos 12 signes en cercle avec Soleil et Ascendant), utilisez la tuile <em>Roue du thème</em> sur l'accueil.","g.synth.h2":"4. Synthèse","g.synth.ou":"Onglet « Synthèse »","g.synth.p1":"Une lecture d'ensemble qui relie vos trois piliers : <strong>Soleil × Ascendant × chemin de vie</strong>, avec la combinaison de vos <strong>éléments</strong> dominants (feu, terre, air, eau) et le fil directeur de votre personnalité.","g.profils.h2":"5. Mes profils","g.profils.ou":"Accueil → tuile « Mes profils » 👪","g.profils.p1":"Enregistrez les personnes et les animaux de votre entourage :","g.profils.li1":"<strong>Ajouter une personne</strong> : prénom, type de relation (conjoint·e, enfant, parent, frère/sœur, ami·e, collègue…), date, heure et lieu de naissance, et une <strong>photo</strong>.","g.profils.li2":"<strong>Modifier</strong> (✎) ou <strong>supprimer</strong> (🗑) un profil à tout moment.","g.profils.li3":"Touchez une personne pour voir sa <strong>fiche complète</strong> : signe, ascendant, chemin de vie et ses nombres — puis accédez à votre compatibilité.","g.compat.h2":"6. Compatibilité","g.compat.ou":"Accueil → « Compatibilité », ou depuis un profil","g.compat.p1":"Comparez votre thème à celui d'un proche sur <strong>8 dimensions</strong> notées, avec barres de progression : amour, passion, amitié, communication, travail, valeurs, quotidien, stabilité — plus vos <strong>forces</strong> et vos <strong>points de vigilance</strong>. La liste de vos proches est <strong>classée par score</strong> dans « Mes profils ».","g.animaux.h2":"7. Animaux de la famille","g.animaux.ou":"« Mes profils » → Ajouter un animal, ou tuile Animaux 🐾","g.animaux.p1":"La numérologie fonctionne aussi pour vos compagnons ! Enregistrez un animal (nom, espèce, date, photo) et touchez-le pour voir sa <strong>fiche numérologique</strong> : son nombre, son caractère et un conseil. (Pas d'horoscope pour les animaux : la numérologie suffit.)","g.bio.h2":"8. Biorythmes","g.bio.ou":"Accueil → tuile « Biorythmes » 📈","g.bio.p1":"Vos trois cycles du jour — <strong>physique</strong> (23 j), <strong>émotionnel</strong> (28 j), <strong>intellectuel</strong> (33 j) — comptés depuis votre naissance, avec les <strong>jours critiques</strong> et une courbe des prochains jours.","g.prev.h2":"9. Prévisions & calendrier","g.prev.ou":"Accueil → tuiles « Prévisions » 📅 et « Calendrier »","g.prev.li1":"<strong>Prévisions</strong> : la vibration de chacun de vos 12 prochains mois et son nombre de jours porteurs.","g.prev.li2":"<strong>Calendrier</strong> : la grille du mois avec chaque jour coloré (porteur, repos, nombre maître).","g.ciel.h2":"10. Le ciel du moment","g.ciel.ou":"Accueil → tuile « Ciel du moment » 🌌","g.ciel.p1":"Ce qui se passe dans le ciel aujourd'hui : <strong>phase et signe de la Lune</strong>, période de <strong>Mercure rétrograde</strong>, et le <strong>nombre universel</strong> du jour, partagé par tous.","g.guid.h2":"11. Guidance & journal","g.guid.ou":"Onglet « Guidance » · Journal sur l'accueil","g.guid.li1":"<strong>Guidance</strong> : répondez à un court questionnaire de vie et recevez une lecture personnalisée, domaine par domaine (amour, travail, argent, santé, spiritualité) selon votre année personnelle.","g.guid.li2":"<strong>Journal</strong> : notez la résonance de vos journées (1 à 5). La tuile <em>Tendances</em> affiche l'évolution dans le temps.","g.carte.h2":"12. Carte du jour & partage","g.carte.ou":"Accueil → tuile « Carte du jour » 🎴","g.carte.p1":"Une belle image de votre journée (nombre du jour, signe, lune) prête à partager avec vos proches. Un bouton <em>Partager ma journée</em> permet aussi un partage texte rapide.","g.pdf.h2":"13. Rapport PDF complet","g.pdf.ou":"Roue des Réglages ⚙︎ → « Rapport complet (PDF) »","g.pdf.p1":"Exportez tout votre thème (numérologie, astrologie, synthèse, année personnelle) dans un document PDF élégant à garder ou partager.","g.outils.h2":"14. Outils","g.outils.ou":"Accueil → tuile « Outils » 🧰","g.outils.li1":"<strong>Date favorable</strong> : les meilleurs jours à venir selon une intention (lancer, aimer, décider…).","g.outils.li2":"<strong>Prénom / nom d'usage</strong> : testez la vibration d'un prénom ou d'un pseudonyme.","g.outils.li3":"<strong>Adresse / numéro</strong> : le nombre d'un lieu ou d'un numéro.","g.decouvrir.h2":"15. Découvrir","g.decouvrir.ou":"Accueil → tuile « Découvrir » 📖","g.decouvrir.p1":"Une rubrique pédagogique qui explique simplement tout ce que calcule l'app : les nombres, les cycles, la grille d'inclusion, l'astrologie, la synthèse. Idéal pour débuter.","g.widget.h2":"16. Widget écran d'accueil (Android)","g.widget.ou":"Écran d'accueil du téléphone","g.widget.p1":"Posez votre <strong>nombre du jour</strong> directement sur l'écran d'accueil : restez appuyé sur l'écran d'accueil → <strong>Widgets</strong> → <strong>Numerocoon</strong>, puis glissez le widget. Un appui l'ouvre dans l'app.","g.reglages.h2":"17. Réglages","g.reglages.ou":"Roue crantée ⚙︎ en haut à droite","g.reglages.li1":"<strong>Langue</strong> : 9 langues (français, anglais, allemand, italien, portugais, espagnol, suédois, norvégien, finnois).","g.reglages.li2":"<strong>Taille du texte</strong> : petite / normale / grande.","g.reglages.li3":"<strong>Rappel quotidien</strong> : une notification à l'heure de votre choix.","g.reglages.li4":"<strong>Sauvegarde & restauration</strong> : exportez vos données dans un fichier et restaurez-les sur un autre appareil (tout reste local).","g.maj.h2":"18. Mises à jour","g.maj.ou":"Automatique · Réglages ⚙︎ → « Mises à jour »","g.maj.p1":"Au lancement, l'app vérifie s'il existe une version plus récente et vous propose de la télécharger. Vous pouvez aussi vérifier manuellement depuis les Réglages. Vos données sont conservées d'une version à l'autre.","g.conf.h2":"19. Confidentialité","g.conf.ou":"—","g.conf.p1":"Numerocoon ne collecte <strong>aucune donnée</strong> : pas de compte, pas de publicité, pas de traceur. Tout ce que vous saisissez reste sur votre appareil. Détails dans la <a href=\"privacy.html\">politique de confidentialité</a>.","g.conf.astuce":"Numerocoon propose un support d'introspection et de bien-être fondé sur des traditions symboliques. Ce n'est ni une prédiction, ni un avis médical, financier ou juridique.","g.footer.line":"<strong>Numerocoon</strong> — par Bengacoon · <a href=\"index.html\">Accueil</a> · <a href=\"privacy.html\">Confidentialité</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Politique de confidentialité — Numerocoon","priv.hero.title":"Politique de confidentialité","priv.hero.date":"Dernière mise à jour : 1 septembre 2026 · Éditeur : Bengacoon","priv.summary":"<strong>En résumé :</strong> Numerocoon ne collecte, ne transmet et ne partage\n    <strong>aucune donnée personnelle</strong>. Il n'y a ni compte en ligne, ni publicité, ni traceur,\n    ni outil de mesure d'audience. Tout ce que vous saisissez reste <strong>uniquement sur votre\n    appareil</strong>. La seule connexion à Internet sert à vérifier s'il existe une mise à jour de\n    l'application — <em>aucune information vous concernant n'est envoyée</em>.","priv.s1.h2":"1. Qui sommes-nous","priv.s1.p1":"Numerocoon est une application de numérologie et d'horoscope de bien-être, éditée dans le cadre\n  de l'univers Bengacoon. Questions : <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Données que nous collectons","priv.s2.p1":"<strong>Aucune.</strong> Nous ne collectons aucune donnée personnelle. L'application ne crée\n  aucun compte sur un serveur, ne vous identifie pas, et ne contient ni publicité, ni traceur, ni\n  outil d'analyse.","priv.s3.h2":"3. Données enregistrées sur votre appareil","priv.s3.intro":"Pour fonctionner, l'application enregistre certaines informations localement, sur votre seul\n  téléphone (jamais sur un serveur) :","priv.s3.li1":"votre profil : prénom, nom et e-mail éventuels ;","priv.s3.li2":"vos données de naissance : date, heure et lieu (pour le thème et l'ascendant) ;","priv.s3.li3":"les proches et animaux que vous enregistrez (nom, données de naissance, photo) ;","priv.s3.li4":"vos réponses au questionnaire de guidance et les notes de votre journal ;","priv.s3.li5":"vos préférences : langue, taille du texte, heure du rappel quotidien.","priv.s3.outro":"Ces données ne quittent jamais votre appareil et ne nous sont jamais transmises.","priv.s4.h2":"4. Permissions et accès réseau","priv.s4.li1":"<strong>Notifications</strong> : uniquement pour le rappel quotidien que vous activez.","priv.s4.li2":"<strong>Photos</strong> : uniquement si vous ajoutez une photo à un profil ; l'image reste sur votre appareil.","priv.s4.li3":"<strong>Internet</strong> : uniquement pour <strong>vérifier l'existence d'une mise à jour</strong>. <strong>Aucune donnée vous concernant n'est envoyée.</strong>","priv.s4.p1":"L'application ne demande pas l'accès à la localisation, aux contacts, au micro ou à la caméra.\n  Le lieu de naissance est choisi dans une liste intégrée.","priv.s5.h2":"5. Partage avec des tiers","priv.s5.p1":"Aucun. Le partage (« Partager ma journée », carte du jour, sauvegarde, PDF) utilise le partage\n  de votre système : le contenu n'est transmis qu'à l'application que <em>vous</em> choisissez. La\n  vérification de mise à jour contacte GitHub, qui peut techniquement enregistrer l'adresse IP à\n  l'origine de la requête ; nous n'y avons pas accès.","priv.s6.h2":"6. Conservation et suppression","priv.s6.p1":"Vos données restent sur votre appareil tant que vous le souhaitez. Vous pouvez les exporter,\n  les restaurer, les effacer depuis les Réglages, ou tout supprimer en désinstallant l'application.","priv.s7.h2":"7. Enfants","priv.s7.p1":"L'application ne s'adresse pas particulièrement aux enfants et ne collecte aucune donnée les\n  concernant.","priv.s8.h2":"8. Avertissement bien-être","priv.s8.p1":"Numerocoon propose un support d'introspection et de bien-être fondé sur des traditions\n  symboliques. Ce n'est ni une prédiction, ni un dispositif médical, ni un avis financier ou\n  juridique.","priv.footer":"<strong>Numerocoon</strong> — par Bengacoon · <a href=\"index.html\">Accueil</a> ·\n    <a href=\"guide.html\">Guide</a> · © 2026 Bengacoon<br>\n    Contact : <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Thème &amp; langue","idx.ver.v210.desc":"Choisissez l’apparence : fond clair, sombre ou selon votre téléphone. Et l’interface est désormais entièrement traduite, jusqu’aux réglages."},"en":{"idx.meta.title":"Numerocoon — Numerology & wellness horoscope","idx.meta.desc":"Numerocoon, by Bengacoon: your detailed numerology chart, your rising sign calculated from your birth time, horoscope, compatibility and guidance. Free, in 9 languages.","brand.by":"by Bengacoon","nav.home":"Home","nav.features":"Features","nav.guide":"Guide","nav.privacy":"Privacy","idx.hero.lead":"Numerology & horoscope in one place. From your date, time and place of birth, discover your chart, your rising sign and guidance that truly fits you.","idx.store.android":"<small>Android · direct APK</small>Download","idx.store.play":"<small>Coming soon to</small>Google&nbsp;Play","idx.store.ios":"<small>Coming soon to</small>App&nbsp;Store","idx.func.eyebrow":"What the app does","idx.func.h2":"A complete portrait, gently drawn","idx.func.sub":"Understand your numbers, read your sky and move forward day by day — no account, no jargon.","idx.card.numero.h3":"Detailed numerology","idx.card.numero.p":"Life path, expression, soul, personality, challenges and cycles, inclusion grid and karmic debts. Right down to the shadow side of each number, for an honest portrait.","idx.card.ascendant.h3":"Rising sign & horoscope","idx.card.ascendant.p":"Your sun sign and your rising sign, calculated astronomically from your time and place of birth. Daily and weekly horoscope, plus favorable days.","idx.card.synthese.h3":"Synthesis","idx.card.synthese.p":"A reading that ties it all together: Sun × Rising sign × life path, and the combination of your dominant elements — fire, earth, air, water.","idx.card.compat.h3":"Detailed compatibility","idx.card.compat.p":"Save your loved ones and compare your charts across 8 rated dimensions — love, passion, friendship, communication, work, values, daily life, stability — with strengths and points to watch.","idx.card.guidance.h3":"Guidance & journal","idx.card.guidance.p":"A life questionnaire, then personalized guidance area by area based on your personal year. A journal to note how each day resonates with you.","idx.card.rappel.h3":"Reminder & sharing","idx.card.rappel.p":"A daily reminder at the time of your choice so you never miss a thing, and one-tap sharing of your day whenever you like.","idx.free.price":"100% free","idx.free.h2":"Everything included, no ads","idx.free.sub":"No purchase, no subscription, no locked features.","idx.free.li1":"Full numerology chart","idx.free.li2":"Rising sign, horoscope and favorable days","idx.free.li3":"Synthesis, compatibility and guidance","idx.free.li4":"Journal, reminders and sharing","idx.free.note":"Numerocoon is a gift from the Bengacoon galaxy — to explore freely.","idx.lang.eyebrow":"For everyone","idx.lang.h2":"Available in 9 languages","idx.lang.sub":"The app is fully translated, right down to the guidance texts.","idx.ver.eyebrow":"Always evolving","idx.ver.h2":"The latest versions","idx.ver.sub":"Numerocoon evolves regularly — here's what's new lately. The full history is on GitHub.","idx.ver.v1.label":"Animal profile","idx.ver.v1.desc":"An animal's profile is far more complete: strengths, needs, place in the family, a kind word and the energy of the day.","idx.ver.v2.label":"Icon & guide","idx.ver.v2.desc":"New icon (golden medallion, crescent moon) and a complete built-in user guide, available offline.","idx.ver.v3.label":"Profiles & photos","idx.ver.v3.desc":"A photo on every profile, a person's full profile (sign, rising sign, numbers) and the numerology profile of your animals.","idx.ver.v4.label":"Profiles & animals","idx.ver.v4.desc":"Manage several profiles (partner, children, family…) with add/edit/delete and a compatibility list, plus profiles for your animals.","idx.ver.v5.label":"Calendar & sky","idx.ver.v5.desc":"Monthly numerology calendar, \"sky of the moment\" (Moon, Mercury retrograde, universal number) and the numerology of your pet.","idx.ver.v6.label":"Home widget","idx.ver.v6.desc":"An Android widget to place your number of the day right on your phone's home screen.","idx.ver.v7.label":"Card, wheel & forecasts","idx.ver.v7.desc":"A card of the day to share, a chart wheel (Sun + Rising sign), 12-month forecasts, journal trends, backup/restore, adjustable text size and a welcome tour.","idx.ver.v8.label":"Direct updates","idx.ver.v8.desc":"The direct APK version now downloads and installs its updates from within the app, without going through the browser.","idx.ver.v9.label":"Biorhythms & PDF","idx.ver.v9.desc":"Biorhythms of the day (physical, emotional, intellectual), a \"Discover\" section to understand it all, and export of your full chart to PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Alignment of the iOS and Android versions and preparation for publishing on both platforms.","idx.ver.v11.label":"Settings &amp; brand","idx.ver.v11.desc":"A cogwheel to access Settings and the \"by Bengacoon\" signature on the home screen.","idx.ver.v12.label":"100% translated","idx.ver.v12.desc":"Complete localization, right down to the assembled sentences, in all 9 languages.","idx.ver.more":"See the full version history →","idx.priv.eyebrow":"Your data, with you","idx.priv.h2":"Nothing leaves your phone","idx.priv.sub":"No account to create, no personal data collected. Your profile and your loved ones stay on your device. The only connection is used to check for updates — without sending anything about you.","idx.footer":"<strong>Numerocoon</strong> — by Bengacoon · Available in 9 languages<br>\n    <a href=\"guide.html\">User guide</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Privacy policy</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon offers a tool for introspection and wellbeing based on symbolic traditions (numerology, astrology). It is not a prediction, a medical device, or financial or legal advice, and it does not replace the advice of a qualified professional.</p>","g.meta.title":"User guide — Numerocoon","g.meta.desc":"The complete guide to Numerocoon: everything you can do (numerology, rising sign, horoscope, compatibility, profiles, biorhythms…) and how.","g.hero.h1":"User guide","g.hero.p":"Everything you can do with Numerocoon, and how. The app is in 9 languages; this guide is in English.","g.toc.title":"Contents","g.toc.1":"1. Getting started","g.toc.2":"2. Numerology","g.toc.3":"3. Astrology","g.toc.4":"4. Synthesis","g.toc.5":"5. My profiles","g.toc.6":"6. Compatibility","g.toc.7":"7. Animals","g.toc.8":"8. Biorhythms","g.toc.9":"9. Forecasts & calendar","g.toc.10":"10. The sky of the moment","g.toc.11":"11. Guidance & journal","g.toc.12":"12. Card & sharing","g.toc.13":"13. PDF report","g.toc.14":"14. Tools","g.toc.15":"15. Discover","g.toc.16":"16. Widget","g.toc.17":"17. Settings","g.toc.18":"18. Updates","g.toc.19":"19. Privacy","g.intro.note":"Each section shows <strong style=\"color:var(--amethyste)\">where to find it</strong> in the app (tab at the bottom, Settings cogwheel at the top right, or the quick-access tiles on the home screen).","g.demarrer.h2":"1. Getting started — create your profile","g.demarrer.ou":"On first launch","g.demarrer.p1":"When you open it, Numerocoon asks you to create your profile. Fill in:","g.demarrer.li1":"<strong>First name</strong> (required), last name and email optional;","g.demarrer.li2":"<strong>Date of birth</strong> (day, month, year);","g.demarrer.li3":"<strong>Time of birth</strong> and <strong>place</strong> — needed to calculate your <em>rising sign</em> (optional, but recommended).","g.demarrer.astuce":"🔒 Everything stays on your device: no online account, no data sent. A welcome tour introduces the app on first launch.","g.num.h2":"2. Numerology","g.num.ou":"\"Numerology\" tab","g.num.p1":"Your complete Pythagorean numerology chart:","g.num.li1":"<strong>Life path</strong>: your main number, with its portrait (strengths, challenges, in love, at work, advice).","g.num.li2":"<strong>Shadow side</strong>: the hidden face of your number and its affirmation.","g.num.li3":"<strong>Name numbers</strong>: expression, soul, personality, active, hereditary, birth number.","g.num.li4":"<strong>Inclusion grid</strong>: your assets and your lessons based on your name.","g.num.li5":"<strong>Karmic debts</strong> (13, 14, 16, 19), <strong>challenges</strong> and <strong>life cycles</strong>.","g.num.li6":"<strong>Personal year</strong>: the theme of your current year.","g.astro.h2":"3. Astrology & horoscope","g.astro.ou":"\"Horoscope\" tab","g.astro.li1":"<strong>Sun sign</strong> and <strong>rising sign</strong> (calculated astronomically from your time and place of birth).","g.astro.li2":"<strong>Daily</strong> and <strong>weekly</strong> horoscope, by area of life.","g.astro.li3":"<strong>Favorable days</strong> of the month.","g.astro.li4":"Quick <strong>compatibility</strong> between signs.","g.astro.p1":"For the <strong>wheel of your chart</strong> (your 12 signs in a circle with Sun and Rising sign), use the <em>Chart wheel</em> tile on the home screen.","g.synth.h2":"4. Synthesis","g.synth.ou":"\"Synthesis\" tab","g.synth.p1":"An overall reading that ties together your three pillars: <strong>Sun × Rising sign × life path</strong>, with the combination of your dominant <strong>elements</strong> (fire, earth, air, water) and the common thread of your personality.","g.profils.h2":"5. My profiles","g.profils.ou":"Home → \"My profiles\" tile 👪","g.profils.p1":"Save the people and animals around you:","g.profils.li1":"<strong>Add a person</strong>: first name, type of relationship (partner, child, parent, sibling, friend, colleague…), date, time and place of birth, and a <strong>photo</strong>.","g.profils.li2":"<strong>Edit</strong> (✎) or <strong>delete</strong> (🗑) a profile at any time.","g.profils.li3":"Tap a person to see their <strong>full profile</strong>: sign, rising sign, life path and their numbers — then access your compatibility.","g.compat.h2":"6. Compatibility","g.compat.ou":"Home → \"Compatibility\", or from a profile","g.compat.p1":"Compare your chart with a loved one's across <strong>8 rated dimensions</strong>, with progress bars: love, passion, friendship, communication, work, values, daily life, stability — plus your <strong>strengths</strong> and your <strong>points to watch</strong>. The list of your loved ones is <strong>ranked by score</strong> in \"My profiles\".","g.animaux.h2":"7. Family animals","g.animaux.ou":"\"My profiles\" → Add an animal, or the Animals tile 🐾","g.animaux.p1":"Numerology works for your companions too! Save an animal (name, species, date, photo) and tap it to see its <strong>numerology profile</strong>: its number, its character and a piece of advice. (No horoscope for animals: numerology is enough.)","g.bio.h2":"8. Biorhythms","g.bio.ou":"Home → \"Biorhythms\" tile 📈","g.bio.p1":"Your three cycles of the day — <strong>physical</strong> (23 d), <strong>emotional</strong> (28 d), <strong>intellectual</strong> (33 d) — counted from your birth, with the <strong>critical days</strong> and a curve of the days ahead.","g.prev.h2":"9. Forecasts & calendar","g.prev.ou":"Home → \"Forecasts\" 📅 and \"Calendar\" tiles","g.prev.li1":"<strong>Forecasts</strong>: the vibration of each of your next 12 months and its number of favorable days.","g.prev.li2":"<strong>Calendar</strong>: the month's grid with each day colored (favorable, rest, master number).","g.ciel.h2":"10. The sky of the moment","g.ciel.ou":"Home → \"Sky of the moment\" tile 🌌","g.ciel.p1":"What's happening in the sky today: the <strong>Moon's phase and sign</strong>, the <strong>Mercury retrograde</strong> period, and the <strong>universal number</strong> of the day, shared by everyone.","g.guid.h2":"11. Guidance & journal","g.guid.ou":"\"Guidance\" tab · Journal on the home screen","g.guid.li1":"<strong>Guidance</strong>: answer a short life questionnaire and receive a personalized reading, area by area (love, work, money, health, spirituality) based on your personal year.","g.guid.li2":"<strong>Journal</strong>: note how your days resonate (1 to 5). The <em>Trends</em> tile shows the change over time.","g.carte.h2":"12. Card of the day & sharing","g.carte.ou":"Home → \"Card of the day\" tile 🎴","g.carte.p1":"A beautiful image of your day (number of the day, sign, moon) ready to share with your loved ones. A <em>Share my day</em> button also allows quick text sharing.","g.pdf.h2":"13. Full PDF report","g.pdf.ou":"Settings cogwheel ⚙︎ → \"Full report (PDF)\"","g.pdf.p1":"Export your entire chart (numerology, astrology, synthesis, personal year) into an elegant PDF document to keep or share.","g.outils.h2":"14. Tools","g.outils.ou":"Home → \"Tools\" tile 🧰","g.outils.li1":"<strong>Favorable date</strong>: the best days ahead for a given intention (to launch, to love, to decide…).","g.outils.li2":"<strong>First name / chosen name</strong>: test the vibration of a first name or a pseudonym.","g.outils.li3":"<strong>Address / number</strong>: the number of a place or a house number.","g.decouvrir.h2":"15. Discover","g.decouvrir.ou":"Home → \"Discover\" tile 📖","g.decouvrir.p1":"An educational section that simply explains everything the app calculates: the numbers, the cycles, the inclusion grid, astrology, the synthesis. Ideal for beginners.","g.widget.h2":"16. Home screen widget (Android)","g.widget.ou":"Phone home screen","g.widget.p1":"Place your <strong>number of the day</strong> right on your home screen: press and hold the home screen → <strong>Widgets</strong> → <strong>Numerocoon</strong>, then drag the widget. A tap opens it in the app.","g.reglages.h2":"17. Settings","g.reglages.ou":"Cogwheel ⚙︎ at the top right","g.reglages.li1":"<strong>Language</strong>: 9 languages (French, English, German, Italian, Portuguese, Spanish, Swedish, Norwegian, Finnish).","g.reglages.li2":"<strong>Text size</strong>: small / normal / large.","g.reglages.li3":"<strong>Daily reminder</strong>: a notification at the time of your choice.","g.reglages.li4":"<strong>Backup & restore</strong>: export your data to a file and restore it on another device (everything stays local).","g.maj.h2":"18. Updates","g.maj.ou":"Automatic · Settings ⚙︎ → \"Updates\"","g.maj.p1":"On launch, the app checks whether a newer version exists and offers to download it. You can also check manually from Settings. Your data is kept from one version to the next.","g.conf.h2":"19. Privacy","g.conf.ou":"—","g.conf.p1":"Numerocoon collects <strong>no data</strong>: no account, no ads, no tracker. Everything you enter stays on your device. Details in the <a href=\"privacy.html\">privacy policy</a>.","g.conf.astuce":"Numerocoon offers a tool for introspection and wellbeing based on symbolic traditions. It is not a prediction, or medical, financial or legal advice.","g.footer.line":"<strong>Numerocoon</strong> — by Bengacoon · <a href=\"index.html\">Home</a> · <a href=\"privacy.html\">Privacy</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Privacy policy — Numerocoon","priv.hero.title":"Privacy policy","priv.hero.date":"Last updated: September 1, 2026 · Publisher: Bengacoon","priv.summary":"<strong>In short:</strong> Numerocoon collects, transmits and shares\n    <strong>no personal data</strong>. There is no online account, no advertising, no tracker,\n    and no audience-measurement tool. Everything you enter stays <strong>solely on your\n    device</strong>. The only internet connection is used to check whether an update to the\n    application exists — <em>no information about you is sent</em>.","priv.s1.h2":"1. Who we are","priv.s1.p1":"Numerocoon is a numerology and wellness horoscope application, published as part\n  of the Bengacoon universe. Questions: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Data we collect","priv.s2.p1":"<strong>None.</strong> We collect no personal data. The application creates\n  no account on a server, does not identify you, and contains no advertising, no tracker, and no\n  analytics tool.","priv.s3.h2":"3. Data stored on your device","priv.s3.intro":"To function, the application stores certain information locally, on your phone alone\n  (never on a server):","priv.s3.li1":"your profile: first name, and possibly last name and email;","priv.s3.li2":"your birth data: date, time and place (for the chart and the rising sign);","priv.s3.li3":"the loved ones and animals you save (name, birth data, photo);","priv.s3.li4":"your answers to the guidance questionnaire and the notes in your journal;","priv.s3.li5":"your preferences: language, text size, time of the daily reminder.","priv.s3.outro":"This data never leaves your device and is never transmitted to us.","priv.s4.h2":"4. Permissions and network access","priv.s4.li1":"<strong>Notifications</strong>: only for the daily reminder that you enable.","priv.s4.li2":"<strong>Photos</strong>: only if you add a photo to a profile; the image stays on your device.","priv.s4.li3":"<strong>Internet</strong>: only to <strong>check whether an update exists</strong>. <strong>No information about you is sent.</strong>","priv.s4.p1":"The application does not request access to location, contacts, the microphone or the camera.\n  The place of birth is chosen from a built-in list.","priv.s5.h2":"5. Sharing with third parties","priv.s5.p1":"None. Sharing (\"Share my day\", card of the day, backup, PDF) uses your system's\n  share feature: the content is only transmitted to the application that <em>you</em> choose. The\n  update check contacts GitHub, which can technically log the IP address behind the\n  request; we do not have access to it.","priv.s6.h2":"6. Retention and deletion","priv.s6.p1":"Your data stays on your device for as long as you wish. You can export it,\n  restore it, erase it from Settings, or delete everything by uninstalling the application.","priv.s7.h2":"7. Children","priv.s7.p1":"The application is not aimed specifically at children and collects no data\n  concerning them.","priv.s8.h2":"8. Wellbeing disclaimer","priv.s8.p1":"Numerocoon offers a tool for introspection and wellbeing based on symbolic\n  traditions. It is not a prediction, a medical device, or financial or\n  legal advice.","priv.footer":"<strong>Numerocoon</strong> — by Bengacoon · <a href=\"index.html\">Home</a> ·\n    <a href=\"guide.html\">Guide</a> · © 2026 Bengacoon<br>\n    Contact: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Theme &amp; language","idx.ver.v210.desc":"Choose the look: light or dark background, or match your phone. And the interface is now fully translated, down to the settings."},"de":{"idx.meta.title":"Numerocoon — Numerologie & Wohlfühl-Horoskop","idx.meta.desc":"Numerocoon, von Bengacoon: Ihr detailliertes numerologisches Profil, Ihr aus der Geburtszeit berechneter Aszendent, Horoskop, Kompatibilität und Guidance. Kostenlos, in 9 Sprachen.","brand.by":"von Bengacoon","nav.home":"Startseite","nav.features":"Funktionen","nav.guide":"Anleitung","nav.privacy":"Datenschutz","idx.hero.lead":"Numerologie & Horoskop vereint. Aus Ihrem Geburtsdatum, Ihrer Geburtszeit und Ihrem Geburtsort entdecken Sie Ihr Profil, Ihren Aszendenten und eine Guidance, die zu Ihnen passt.","idx.store.android":"<small>Android · APK direkt</small>Herunterladen","idx.store.play":"<small>Bald bei</small>Google&nbsp;Play","idx.store.ios":"<small>Bald im</small>App&nbsp;Store","idx.func.eyebrow":"Was die App kann","idx.func.h2":"Ein vollständiges Porträt, ganz sanft","idx.func.sub":"Verstehen Sie Ihre Zahlen, lesen Sie Ihren Himmel und kommen Sie Tag für Tag voran — ohne Konto, ohne Fachjargon.","idx.card.numero.h3":"Detaillierte Numerologie","idx.card.numero.p":"Lebensweg, Ausdruck, Seele, Persönlichkeit, Herausforderungen und Zyklen, Einschlussgitter und karmische Schulden. Bis hin zur Schattenseite jeder Zahl, für ein ehrliches Porträt.","idx.card.ascendant.h3":"Aszendent & Horoskop","idx.card.ascendant.p":"Ihr Sonnenzeichen und Ihr Aszendent, astronomisch aus Geburtszeit und -ort berechnet. Horoskop für den Tag, die Woche und die günstigen Tage.","idx.card.synthese.h3":"Synthese","idx.card.synthese.p":"Eine Deutung, die alles verbindet: Sonne × Aszendent × Lebensweg und die Kombination Ihrer dominanten Elemente — Feuer, Erde, Luft, Wasser.","idx.card.compat.h3":"Detaillierte Kompatibilität","idx.card.compat.p":"Speichern Sie Ihre Liebsten und vergleichen Sie Ihre Profile in 8 bewerteten Dimensionen — Liebe, Leidenschaft, Freundschaft, Kommunikation, Arbeit, Werte, Alltag, Stabilität — mit Stärken und Achtungspunkten.","idx.card.guidance.h3":"Guidance & Tagebuch","idx.card.guidance.p":"Ein Lebensfragebogen und anschließend eine persönliche Guidance Bereich für Bereich, passend zu Ihrem persönlichen Jahr. Ein Tagebuch, um die Resonanz Ihrer Tage festzuhalten.","idx.card.rappel.h3":"Erinnerung & Teilen","idx.card.rappel.p":"Eine tägliche Erinnerung zur Uhrzeit Ihrer Wahl, damit Sie nichts verpassen, und das Teilen Ihres Tages mit einer Geste, wann immer Sie möchten.","idx.free.price":"100 % kostenlos","idx.free.h2":"Alles inklusive, ohne Werbung","idx.free.sub":"Kein Kauf, kein Abo, keine gesperrte Funktion.","idx.free.li1":"Vollständiges numerologisches Profil","idx.free.li2":"Aszendent, Horoskop und günstige Tage","idx.free.li3":"Synthese, Kompatibilität und Guidance","idx.free.li4":"Tagebuch, Erinnerungen und Teilen","idx.free.note":"Numerocoon ist ein Geschenk der Bengacoon-Galaxie — ganz frei zu entdecken.","idx.lang.eyebrow":"Für alle","idx.lang.h2":"Verfügbar in 9 Sprachen","idx.lang.sub":"Die App ist vollständig übersetzt, bis hin zu den Guidance-Texten.","idx.ver.eyebrow":"Immer in Bewegung","idx.ver.h2":"Die neuesten Versionen","idx.ver.sub":"Numerocoon entwickelt sich stetig weiter — hier sind die jüngsten Neuerungen. Die vollständige Historie finden Sie auf GitHub.","idx.ver.v1.label":"Tierprofil","idx.ver.v1.desc":"Das Profil eines Tieres ist deutlich vollständiger: Stärken, Bedürfnisse, Platz in der Familie, liebe Worte und Energie des Tages.","idx.ver.v2.label":"Icon & Anleitung","idx.ver.v2.desc":"Neues Icon (Goldmedaillon, Mondsichel) und eine vollständige integrierte Bedienungsanleitung, auch offline verfügbar.","idx.ver.v3.label":"Profile & Fotos","idx.ver.v3.desc":"Ein Foto auf jedem Profil, das vollständige Profil einer Person (Zeichen, Aszendent, Zahlen) und das numerologische Profil der Tiere.","idx.ver.v4.label":"Profile & Tiere","idx.ver.v4.desc":"Verwalten Sie mehrere Profile (Partner, Kinder, Familie …) mit Hinzufügen/Bearbeiten/Löschen und Kompatibilitätsliste, dazu Profile für Ihre Tiere.","idx.ver.v5.label":"Kalender & Himmel","idx.ver.v5.desc":"Numerologischer Kalender des Monats, „Himmel des Augenblicks“ (Mond, rückläufiger Merkur, Universalzahl) und Numerologie Ihres Haustiers.","idx.ver.v6.label":"Startbildschirm-Widget","idx.ver.v6.desc":"Ein Android-Widget, um Ihre Zahl des Tages direkt auf den Startbildschirm Ihres Telefons zu legen.","idx.ver.v7.label":"Karte, Rad & Prognosen","idx.ver.v7.desc":"Teilbare Tageskarte, Themenrad (Sonne + Aszendent), Prognosen über 12 Monate, Tagebuchtrends, Sicherung/Wiederherstellung, einstellbare Textgröße und Willkommensrundgang.","idx.ver.v8.label":"Direkte Updates","idx.ver.v8.desc":"Die direkte APK-Version lädt und installiert ihre Updates nun aus der App heraus, ohne den Umweg über den Browser.","idx.ver.v9.label":"Biorhythmen & PDF","idx.ver.v9.desc":"Biorhythmen des Tages (körperlich, emotional, intellektuell), Rubrik „Entdecken“ zum Verständnis von allem und Export des vollständigen Profils als PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Angleichung der iOS- und Android-Versionen und Vorbereitung der Veröffentlichung auf beiden Plattformen.","idx.ver.v11.label":"Einstellungen &amp; Marke","idx.ver.v11.desc":"Zahnrad für den Zugang zu den Einstellungen und Signatur „von Bengacoon“ auf der Startseite.","idx.ver.v12.label":"100 % übersetzt","idx.ver.v12.desc":"Vollständige Lokalisierung, bis hin zu den zusammengesetzten Sätzen, in den 9 Sprachen.","idx.ver.more":"Gesamte Versionshistorie ansehen →","idx.priv.eyebrow":"Ihre Daten, bei Ihnen","idx.priv.h2":"Nichts verlässt Ihr Telefon","idx.priv.sub":"Kein Konto zu erstellen, keine personenbezogenen Daten erhoben. Ihr Profil und Ihre Liebsten bleiben auf Ihrem Gerät. Die einzige Verbindung dient dazu, nach Updates zu suchen — ohne etwas über Sie zu senden.","idx.footer":"<strong>Numerocoon</strong> — von Bengacoon · Verfügbar in 9 Sprachen<br>\n    <a href=\"guide.html\">Bedienungsanleitung</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Datenschutzerklärung</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon bietet eine Stütze zur Selbstreflexion und zum Wohlbefinden auf der Grundlage symbolischer Traditionen (Numerologie, Astrologie). Es ist weder eine Vorhersage noch ein Medizinprodukt noch eine finanzielle oder rechtliche Beratung und ersetzt nicht den Rat einer qualifizierten Fachkraft.</p>","g.meta.title":"Bedienungsanleitung — Numerocoon","g.meta.desc":"Die vollständige Anleitung zu Numerocoon: alles, was Sie tun können (Numerologie, Aszendent, Horoskop, Kompatibilität, Profile, Biorhythmen …) und wie.","g.hero.h1":"Bedienungsanleitung","g.hero.p":"Alles, was Sie mit Numerocoon tun können, und wie. Die App gibt es in 9 Sprachen; diese Anleitung ist auf Deutsch.","g.toc.title":"Inhalt","g.toc.1":"1. Loslegen","g.toc.2":"2. Numerologie","g.toc.3":"3. Astrologie","g.toc.4":"4. Synthese","g.toc.5":"5. Meine Profile","g.toc.6":"6. Kompatibilität","g.toc.7":"7. Tiere","g.toc.8":"8. Biorhythmen","g.toc.9":"9. Prognosen & Kalender","g.toc.10":"10. Der Himmel des Augenblicks","g.toc.11":"11. Guidance & Tagebuch","g.toc.12":"12. Karte & Teilen","g.toc.13":"13. PDF-Bericht","g.toc.14":"14. Werkzeuge","g.toc.15":"15. Entdecken","g.toc.16":"16. Widget","g.toc.17":"17. Einstellungen","g.toc.18":"18. Updates","g.toc.19":"19. Datenschutz","g.intro.note":"Jede Rubrik gibt an, <strong style=\"color:var(--amethyste)\">wo Sie sie finden</strong> in der App (Tab unten, Einstellungs-Zahnrad oben rechts oder Schnellzugriff-Kacheln auf der Startseite).","g.demarrer.h2":"1. Loslegen — Ihr Profil erstellen","g.demarrer.ou":"Beim ersten Öffnen","g.demarrer.p1":"Beim Start bittet Numerocoon Sie, Ihr Profil zu erstellen. Geben Sie an:","g.demarrer.li1":"<strong>Vorname</strong> (Pflichtfeld), Nachname und E-Mail optional;","g.demarrer.li2":"<strong>Geburtsdatum</strong> (Tag, Monat, Jahr);","g.demarrer.li3":"<strong>Geburtszeit</strong> und <strong>Geburtsort</strong> — nötig zur Berechnung Ihres <em>Aszendenten</em> (optional, aber empfohlen).","g.demarrer.astuce":"🔒 Alles bleibt auf Ihrem Gerät: kein Online-Konto, keine gesendeten Daten. Ein Willkommensrundgang stellt Ihnen die App beim ersten Start vor.","g.num.h2":"2. Numerologie","g.num.ou":"Tab „Numerologie“","g.num.p1":"Ihr vollständiges pythagoreisches numerologisches Profil:","g.num.li1":"<strong>Lebensweg</strong>: Ihre Hauptzahl mit ihrem Porträt (Stärken, Herausforderungen, in der Liebe, bei der Arbeit, Rat).","g.num.li2":"<strong>Schattenseite</strong>: die verborgene Seite Ihrer Zahl und ihre Affirmation.","g.num.li3":"<strong>Namenszahlen</strong>: Ausdruck, Seele, Persönlichkeit, Aktivzahl, Erbzahl, Geburtszahl.","g.num.li4":"<strong>Einschlussgitter</strong>: Ihre Stärken und Ihre Lektionen anhand Ihres Namens.","g.num.li5":"<strong>Karmische Schulden</strong> (13, 14, 16, 19), <strong>Herausforderungen</strong> und <strong>Lebenszyklen</strong>.","g.num.li6":"<strong>Persönliches Jahr</strong>: das Thema Ihres laufenden Jahres.","g.astro.h2":"3. Astrologie & Horoskop","g.astro.ou":"Tab „Horoskop“","g.astro.li1":"<strong>Sonnenzeichen</strong> und <strong>Aszendent</strong> (astronomisch aus Ihrer Geburtszeit und Ihrem Geburtsort berechnet).","g.astro.li2":"<strong>Horoskop des Tages</strong> und der <strong>Woche</strong>, nach Bereichen.","g.astro.li3":"<strong>Günstige Tage</strong> des Monats.","g.astro.li4":"Schnelle <strong>Kompatibilität</strong> zwischen Zeichen.","g.astro.p1":"Für das <strong>Rad Ihres Profils</strong> (Ihre 12 Zeichen im Kreis mit Sonne und Aszendent) nutzen Sie die Kachel <em>Themenrad</em> auf der Startseite.","g.synth.h2":"4. Synthese","g.synth.ou":"Tab „Synthese“","g.synth.p1":"Eine Gesamtdeutung, die Ihre drei Säulen verbindet: <strong>Sonne × Aszendent × Lebensweg</strong>, mit der Kombination Ihrer dominanten <strong>Elemente</strong> (Feuer, Erde, Luft, Wasser) und dem roten Faden Ihrer Persönlichkeit.","g.profils.h2":"5. Meine Profile","g.profils.ou":"Startseite → Kachel „Meine Profile“ 👪","g.profils.p1":"Speichern Sie die Menschen und Tiere in Ihrem Umfeld:","g.profils.li1":"<strong>Eine Person hinzufügen</strong>: Vorname, Art der Beziehung (Partner·in, Kind, Elternteil, Bruder/Schwester, Freund·in, Kolleg·in …), Geburtsdatum, -zeit und -ort sowie ein <strong>Foto</strong>.","g.profils.li2":"Ein Profil jederzeit <strong>bearbeiten</strong> (✎) oder <strong>löschen</strong> (🗑).","g.profils.li3":"Tippen Sie auf eine Person, um ihr <strong>vollständiges Profil</strong> zu sehen: Zeichen, Aszendent, Lebensweg und ihre Zahlen — und rufen Sie dann Ihre Kompatibilität auf.","g.compat.h2":"6. Kompatibilität","g.compat.ou":"Startseite → „Kompatibilität“ oder aus einem Profil heraus","g.compat.p1":"Vergleichen Sie Ihr Profil mit dem eines Nahestehenden in <strong>8 bewerteten Dimensionen</strong> mit Fortschrittsbalken: Liebe, Leidenschaft, Freundschaft, Kommunikation, Arbeit, Werte, Alltag, Stabilität — dazu Ihre <strong>Stärken</strong> und Ihre <strong>Achtungspunkte</strong>. Die Liste Ihrer Liebsten ist in „Meine Profile“ <strong>nach Punktzahl sortiert</strong>.","g.animaux.h2":"7. Tiere der Familie","g.animaux.ou":"„Meine Profile“ → Ein Tier hinzufügen oder Kachel Tiere 🐾","g.animaux.p1":"Numerologie funktioniert auch für Ihre Gefährten! Speichern Sie ein Tier (Name, Art, Datum, Foto) und tippen Sie darauf, um sein <strong>numerologisches Profil</strong> zu sehen: seine Zahl, seinen Charakter und einen Rat. (Kein Horoskop für Tiere: Numerologie genügt.)","g.bio.h2":"8. Biorhythmen","g.bio.ou":"Startseite → Kachel „Biorhythmen“ 📈","g.bio.p1":"Ihre drei Zyklen des Tages — <strong>körperlich</strong> (23 T.), <strong>emotional</strong> (28 T.), <strong>intellektuell</strong> (33 T.) — gezählt ab Ihrer Geburt, mit den <strong>kritischen Tagen</strong> und einer Kurve für die kommenden Tage.","g.prev.h2":"9. Prognosen & Kalender","g.prev.ou":"Startseite → Kacheln „Prognosen“ 📅 und „Kalender“","g.prev.li1":"<strong>Prognosen</strong>: die Schwingung jedes Ihrer nächsten 12 Monate und die Anzahl seiner tragenden Tage.","g.prev.li2":"<strong>Kalender</strong>: das Monatsraster mit jedem Tag farblich markiert (tragend, Ruhe, Meisterzahl).","g.ciel.h2":"10. Der Himmel des Augenblicks","g.ciel.ou":"Startseite → Kachel „Himmel des Augenblicks“ 🌌","g.ciel.p1":"Was heute am Himmel geschieht: <strong>Phase und Zeichen des Mondes</strong>, Zeitraum eines <strong>rückläufigen Merkur</strong> und die <strong>Universalzahl</strong> des Tages, die alle teilen.","g.guid.h2":"11. Guidance & Tagebuch","g.guid.ou":"Tab „Guidance“ · Tagebuch auf der Startseite","g.guid.li1":"<strong>Guidance</strong>: Beantworten Sie einen kurzen Lebensfragebogen und erhalten Sie eine persönliche Deutung, Bereich für Bereich (Liebe, Arbeit, Geld, Gesundheit, Spiritualität), passend zu Ihrem persönlichen Jahr.","g.guid.li2":"<strong>Tagebuch</strong>: Halten Sie die Resonanz Ihrer Tage fest (1 bis 5). Die Kachel <em>Trends</em> zeigt die Entwicklung im Zeitverlauf.","g.carte.h2":"12. Tageskarte & Teilen","g.carte.ou":"Startseite → Kachel „Tageskarte“ 🎴","g.carte.p1":"Ein schönes Bild Ihres Tages (Zahl des Tages, Zeichen, Mond), bereit zum Teilen mit Ihren Liebsten. Eine Schaltfläche <em>Meinen Tag teilen</em> ermöglicht auch ein schnelles Teilen per Text.","g.pdf.h2":"13. Vollständiger PDF-Bericht","g.pdf.ou":"Einstellungs-Zahnrad ⚙︎ → „Vollständiger Bericht (PDF)“","g.pdf.p1":"Exportieren Sie Ihr gesamtes Profil (Numerologie, Astrologie, Synthese, persönliches Jahr) in ein elegantes PDF-Dokument zum Aufbewahren oder Teilen.","g.outils.h2":"14. Werkzeuge","g.outils.ou":"Startseite → Kachel „Werkzeuge“ 🧰","g.outils.li1":"<strong>Günstiges Datum</strong>: die besten kommenden Tage je nach Absicht (starten, lieben, entscheiden …).","g.outils.li2":"<strong>Vorname / Rufname</strong>: testen Sie die Schwingung eines Vornamens oder eines Pseudonyms.","g.outils.li3":"<strong>Adresse / Nummer</strong>: die Zahl eines Ortes oder einer Nummer.","g.decouvrir.h2":"15. Entdecken","g.decouvrir.ou":"Startseite → Kachel „Entdecken“ 📖","g.decouvrir.p1":"Eine erklärende Rubrik, die einfach alles darlegt, was die App berechnet: die Zahlen, die Zyklen, das Einschlussgitter, die Astrologie, die Synthese. Ideal für den Einstieg.","g.widget.h2":"16. Startbildschirm-Widget (Android)","g.widget.ou":"Startbildschirm des Telefons","g.widget.p1":"Legen Sie Ihre <strong>Zahl des Tages</strong> direkt auf den Startbildschirm: Halten Sie den Startbildschirm gedrückt → <strong>Widgets</strong> → <strong>Numerocoon</strong> und ziehen Sie dann das Widget. Ein Tippen öffnet es in der App.","g.reglages.h2":"17. Einstellungen","g.reglages.ou":"Zahnrad ⚙︎ oben rechts","g.reglages.li1":"<strong>Sprache</strong>: 9 Sprachen (Französisch, Englisch, Deutsch, Italienisch, Portugiesisch, Spanisch, Schwedisch, Norwegisch, Finnisch).","g.reglages.li2":"<strong>Textgröße</strong>: klein / normal / groß.","g.reglages.li3":"<strong>Tägliche Erinnerung</strong>: eine Benachrichtigung zur Uhrzeit Ihrer Wahl.","g.reglages.li4":"<strong>Sicherung & Wiederherstellung</strong>: Exportieren Sie Ihre Daten in eine Datei und stellen Sie sie auf einem anderen Gerät wieder her (alles bleibt lokal).","g.maj.h2":"18. Updates","g.maj.ou":"Automatisch · Einstellungen ⚙︎ → „Updates“","g.maj.p1":"Beim Start prüft die App, ob eine neuere Version vorhanden ist, und bietet Ihnen an, sie herunterzuladen. Sie können auch manuell aus den Einstellungen heraus prüfen. Ihre Daten bleiben von einer Version zur nächsten erhalten.","g.conf.h2":"19. Datenschutz","g.conf.ou":"—","g.conf.p1":"Numerocoon erhebt <strong>keinerlei Daten</strong>: kein Konto, keine Werbung, kein Tracker. Alles, was Sie eingeben, bleibt auf Ihrem Gerät. Einzelheiten in der <a href=\"privacy.html\">Datenschutzerklärung</a>.","g.conf.astuce":"Numerocoon bietet eine Stütze zur Selbstreflexion und zum Wohlbefinden auf der Grundlage symbolischer Traditionen. Es ist weder eine Vorhersage noch eine medizinische, finanzielle oder rechtliche Beratung.","g.footer.line":"<strong>Numerocoon</strong> — von Bengacoon · <a href=\"index.html\">Startseite</a> · <a href=\"privacy.html\">Datenschutz</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Datenschutzerklärung — Numerocoon","priv.hero.title":"Datenschutzerklärung","priv.hero.date":"Letzte Aktualisierung: 1. September 2026 · Herausgeber: Bengacoon","priv.summary":"<strong>Kurz gesagt:</strong> Numerocoon erhebt, übermittelt und teilt\n    <strong>keinerlei personenbezogene Daten</strong>. Es gibt weder ein Online-Konto noch Werbung, noch einen Tracker,\n    noch ein Werkzeug zur Reichweitenmessung. Alles, was Sie eingeben, bleibt <strong>ausschließlich auf Ihrem\n    Gerät</strong>. Die einzige Internetverbindung dient dazu, zu prüfen, ob ein Update der\n    Anwendung vorliegt — <em>es werden keinerlei Informationen über Sie gesendet</em>.","priv.s1.h2":"1. Wer wir sind","priv.s1.p1":"Numerocoon ist eine Anwendung für Numerologie und Wohlfühl-Horoskop, herausgegeben im Rahmen\n  des Bengacoon-Universums. Fragen: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Daten, die wir erheben","priv.s2.p1":"<strong>Keine.</strong> Wir erheben keinerlei personenbezogene Daten. Die Anwendung erstellt\n  kein Konto auf einem Server, identifiziert Sie nicht und enthält weder Werbung noch Tracker, noch ein\n  Analysewerkzeug.","priv.s3.h2":"3. Auf Ihrem Gerät gespeicherte Daten","priv.s3.intro":"Um zu funktionieren, speichert die Anwendung bestimmte Informationen lokal, auf Ihrem alleinigen\n  Telefon (niemals auf einem Server):","priv.s3.li1":"Ihr Profil: gegebenenfalls Vorname, Nachname und E-Mail;","priv.s3.li2":"Ihre Geburtsdaten: Datum, Uhrzeit und Ort (für das Profil und den Aszendenten);","priv.s3.li3":"die Nahestehenden und Tiere, die Sie speichern (Name, Geburtsdaten, Foto);","priv.s3.li4":"Ihre Antworten auf den Guidance-Fragebogen und die Notizen Ihres Tagebuchs;","priv.s3.li5":"Ihre Einstellungen: Sprache, Textgröße, Uhrzeit der täglichen Erinnerung.","priv.s3.outro":"Diese Daten verlassen niemals Ihr Gerät und werden uns niemals übermittelt.","priv.s4.h2":"4. Berechtigungen und Netzwerkzugriff","priv.s4.li1":"<strong>Benachrichtigungen</strong>: ausschließlich für die tägliche Erinnerung, die Sie aktivieren.","priv.s4.li2":"<strong>Fotos</strong>: ausschließlich, wenn Sie einem Profil ein Foto hinzufügen; das Bild bleibt auf Ihrem Gerät.","priv.s4.li3":"<strong>Internet</strong>: ausschließlich, um <strong>das Vorhandensein eines Updates zu prüfen</strong>. <strong>Es werden keinerlei Daten über Sie gesendet.</strong>","priv.s4.p1":"Die Anwendung verlangt keinen Zugriff auf den Standort, die Kontakte, das Mikrofon oder die Kamera.\n  Der Geburtsort wird aus einer integrierten Liste gewählt.","priv.s5.h2":"5. Weitergabe an Dritte","priv.s5.p1":"Keine. Das Teilen („Meinen Tag teilen“, Tageskarte, Sicherung, PDF) nutzt die Teilen-Funktion\n  Ihres Systems: Der Inhalt wird nur an die Anwendung übermittelt, die <em>Sie</em> wählen. Die\n  Update-Prüfung kontaktiert GitHub, das technisch die IP-Adresse speichern kann, von der die Anfrage\n  ausgeht; wir haben keinen Zugriff darauf.","priv.s6.h2":"6. Aufbewahrung und Löschung","priv.s6.p1":"Ihre Daten bleiben auf Ihrem Gerät, solange Sie möchten. Sie können sie exportieren,\n  wiederherstellen, aus den Einstellungen heraus löschen oder alles durch Deinstallieren der Anwendung entfernen.","priv.s7.h2":"7. Kinder","priv.s7.p1":"Die Anwendung richtet sich nicht besonders an Kinder und erhebt keinerlei Daten, die sie\n  betreffen.","priv.s8.h2":"8. Wohlfühl-Hinweis","priv.s8.p1":"Numerocoon bietet eine Stütze zur Selbstreflexion und zum Wohlbefinden auf der Grundlage symbolischer\n  Traditionen. Es ist weder eine Vorhersage noch ein Medizinprodukt, noch eine finanzielle oder\n  rechtliche Beratung.","priv.footer":"<strong>Numerocoon</strong> — von Bengacoon · <a href=\"index.html\">Startseite</a> ·\n    <a href=\"guide.html\">Anleitung</a> · © 2026 Bengacoon<br>\n    Kontakt: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Design &amp; Sprache","idx.ver.v210.desc":"Wählen Sie das Erscheinungsbild: heller oder dunkler Hintergrund – oder nach Ihrem Telefon. Und die Oberfläche ist jetzt vollständig übersetzt, bis in die Einstellungen."},"it":{"idx.meta.title":"Numerocoon — Numerologia & oroscopo del benessere","idx.meta.desc":"Numerocoon, di Bengacoon: il tuo tema numerologico dettagliato, il tuo ascendente calcolato dall'ora di nascita, oroscopo, compatibilità e guida. Gratuito, in 9 lingue.","brand.by":"di Bengacoon","nav.home":"Home","nav.features":"Funzioni","nav.guide":"Guida","nav.privacy":"Privacy","idx.hero.lead":"Numerologia e oroscopo riuniti. A partire dalla tua data, dalla tua ora e dal tuo luogo di nascita, scopri il tuo tema, il tuo ascendente e una guida che ti somiglia.","idx.store.android":"<small>Android · APK diretto</small>Scarica","idx.store.play":"<small>Presto su</small>Google&nbsp;Play","idx.store.ios":"<small>Presto su</small>App&nbsp;Store","idx.func.eyebrow":"Cosa fa l'app","idx.func.h2":"Un ritratto completo, con dolcezza","idx.func.sub":"Comprendere i tuoi numeri, leggere il tuo cielo e avanzare giorno dopo giorno — senza account, senza tecnicismi.","idx.card.numero.h3":"Numerologia dettagliata","idx.card.numero.p":"Sentiero di vita, espressione, anima, personalità, sfide e cicli, griglia di inclusione e debiti karmici. Fino al lato oscuro di ogni numero, per un ritratto onesto.","idx.card.ascendant.h3":"Ascendente & oroscopo","idx.card.ascendant.p":"Il tuo segno solare e il tuo ascendente, calcolato astronomicamente a partire dall'ora e dal luogo di nascita. Oroscopo del giorno, della settimana e giorni favorevoli.","idx.card.synthese.h3":"Sintesi","idx.card.synthese.p":"Una lettura che collega tutto: Sole × Ascendente × sentiero di vita, e la combinazione dei tuoi elementi dominanti — fuoco, terra, aria, acqua.","idx.card.compat.h3":"Compatibilità dettagliata","idx.card.compat.p":"Registra le persone care e confronta i vostri temi su 8 dimensioni valutate — amore, passione, amicizia, comunicazione, lavoro, valori, quotidianità, stabilità — con punti di forza e punti di attenzione.","idx.card.guidance.h3":"Guida & diario","idx.card.guidance.p":"Un questionario di vita, poi una guida personalizzata ambito per ambito in base al tuo anno personale. Un diario per annotare la risonanza delle tue giornate.","idx.card.rappel.h3":"Promemoria & condivisione","idx.card.rappel.p":"Un promemoria quotidiano all'ora che preferisci per non perderti nulla, e la condivisione della tua giornata con un gesto, quando lo desideri.","idx.free.price":"100 % gratuito","idx.free.h2":"Tutto è offerto, senza pubblicità","idx.free.sub":"Nessun acquisto, nessun abbonamento, nessuna funzione bloccata.","idx.free.li1":"Tema numerologico completo","idx.free.li2":"Ascendente, oroscopo e giorni favorevoli","idx.free.li3":"Sintesi, compatibilità e guida","idx.free.li4":"Diario, promemoria e condivisione","idx.free.note":"Numerocoon è un regalo della galassia Bengacoon — da scoprire in tutta libertà.","idx.lang.eyebrow":"Per tutti","idx.lang.h2":"Disponibile in 9 lingue","idx.lang.sub":"L'applicazione è interamente tradotta, fino ai testi di guida.","idx.ver.eyebrow":"Sempre in movimento","idx.ver.h2":"Le ultime versioni","idx.ver.sub":"Numerocoon si evolve regolarmente — ecco le novità recenti. La cronologia completa è su GitHub.","idx.ver.v1.label":"Scheda animale","idx.ver.v1.desc":"La scheda di un animale è molto più completa: punti di forza, bisogni, posto nella famiglia, parola dolce ed energia del giorno.","idx.ver.v2.label":"Icona & guida","idx.ver.v2.desc":"Nuova icona (medaglione d'oro, falce di luna) e una guida all'uso completa integrata, accessibile offline.","idx.ver.v3.label":"Schede & foto","idx.ver.v3.desc":"Una foto su ogni profilo, la scheda completa di una persona (segno, ascendente, numeri) e la scheda numerologica degli animali.","idx.ver.v4.label":"Profili & animali","idx.ver.v4.desc":"Gestisci più profili (partner, figli, famiglia…) con aggiunta/modifica/eliminazione e lista di compatibilità, oltre a profili per i tuoi animali.","idx.ver.v5.label":"Calendario & cielo","idx.ver.v5.desc":"Calendario numerologico del mese, «cielo del momento» (Luna, Mercurio retrogrado, numero universale) e numerologia del tuo animale domestico.","idx.ver.v6.label":"Widget della home","idx.ver.v6.desc":"Un widget Android per mettere il tuo numero del giorno direttamente sulla schermata home del telefono.","idx.ver.v7.label":"Carta, ruota & previsioni","idx.ver.v7.desc":"Carta del giorno da condividere, ruota del tema (Sole + Ascendente), previsioni su 12 mesi, tendenze del diario, backup/ripristino, dimensione del testo regolabile e tour di benvenuto.","idx.ver.v8.label":"Aggiornamenti diretti","idx.ver.v8.desc":"La versione APK diretto ora scarica e installa i propri aggiornamenti dall'applicazione, senza passare dal browser.","idx.ver.v9.label":"Bioritmi & PDF","idx.ver.v9.desc":"Bioritmi del giorno (fisico, emotivo, intellettuale), sezione «Scopri» per capire tutto, ed esportazione del tema completo in PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Allineamento delle versioni iOS e Android e preparazione della pubblicazione su entrambe le piattaforme.","idx.ver.v11.label":"Impostazioni &amp; marchio","idx.ver.v11.desc":"Ruota dentata per accedere alle Impostazioni e firma «di Bengacoon» sulla home.","idx.ver.v12.label":"100 % tradotto","idx.ver.v12.desc":"Localizzazione completa, fino alle frasi assemblate, in tutte le 9 lingue.","idx.ver.more":"Vedi tutta la cronologia delle versioni →","idx.priv.eyebrow":"I tuoi dati, a casa tua","idx.priv.h2":"Niente lascia il tuo telefono","idx.priv.sub":"Nessun account da creare, nessun dato personale raccolto. Il tuo profilo e le persone care restano sul tuo dispositivo. L'unica connessione serve a verificare gli aggiornamenti — senza inviare nulla che ti riguardi.","idx.footer":"<strong>Numerocoon</strong> — di Bengacoon · Disponibile in 9 lingue<br>\n    <a href=\"guide.html\">Guida all'uso</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Politica sulla privacy</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon propone un supporto di introspezione e benessere fondato su tradizioni simboliche (numerologia, astrologia). Non è né una previsione, né un dispositivo medico, né un parere finanziario o legale, e non sostituisce il parere di un professionista qualificato.</p>","g.meta.title":"Guida all'uso — Numerocoon","g.meta.desc":"La guida completa di Numerocoon: tutto ciò che puoi fare (numerologia, ascendente, oroscopo, compatibilità, profili, bioritmi…) e come.","g.hero.h1":"Guida all'uso","g.hero.p":"Tutto ciò che puoi fare con Numerocoon, e come. L'applicazione è in 9 lingue; questa guida è in italiano.","g.toc.title":"Indice","g.toc.1":"1. Iniziare","g.toc.2":"2. Numerologia","g.toc.3":"3. Astrologia","g.toc.4":"4. Sintesi","g.toc.5":"5. I miei profili","g.toc.6":"6. Compatibilità","g.toc.7":"7. Animali","g.toc.8":"8. Bioritmi","g.toc.9":"9. Previsioni & calendario","g.toc.10":"10. Il cielo del momento","g.toc.11":"11. Guida & diario","g.toc.12":"12. Carta & condivisione","g.toc.13":"13. Report PDF","g.toc.14":"14. Strumenti","g.toc.15":"15. Scopri","g.toc.16":"16. Widget","g.toc.17":"17. Impostazioni","g.toc.18":"18. Aggiornamenti","g.toc.19":"19. Privacy","g.intro.note":"Ogni sezione indica <strong style=\"color:var(--amethyste)\">dove trovarla</strong> nell'applicazione (scheda in basso, ruota delle Impostazioni in alto a destra, o riquadri di accesso rapido della home).","g.demarrer.h2":"1. Iniziare — creare il tuo profilo","g.demarrer.ou":"Alla prima apertura","g.demarrer.p1":"All'avvio, Numerocoon ti chiede di creare il tuo profilo. Inserisci:","g.demarrer.li1":"<strong>Nome</strong> (obbligatorio), cognome ed e-mail facoltativi;","g.demarrer.li2":"<strong>Data di nascita</strong> (giorno, mese, anno);","g.demarrer.li3":"<strong>Ora di nascita</strong> e <strong>luogo</strong> — necessari per calcolare il tuo <em>ascendente</em> (facoltativi, ma consigliati).","g.demarrer.astuce":"🔒 Tutto resta sul tuo dispositivo: nessun account online, nessun dato inviato. Un tour di benvenuto ti presenta l'app al primo avvio.","g.num.h2":"2. Numerologia","g.num.ou":"Scheda «Numerologia»","g.num.p1":"Il tuo tema numerologico pitagorico completo:","g.num.li1":"<strong>Sentiero di vita</strong>: il tuo numero principale, con il suo ritratto (punti di forza, sfide, in amore, sul lavoro, consiglio).","g.num.li2":"<strong>Lato oscuro</strong>: il volto nascosto del tuo numero e la sua affermazione.","g.num.li3":"<strong>Numeri del nome</strong>: espressione, anima, personalità, attivo, ereditario, numero di nascita.","g.num.li4":"<strong>Griglia di inclusione</strong>: i tuoi punti di forza e le tue lezioni in base al tuo nome.","g.num.li5":"<strong>Debiti karmici</strong> (13, 14, 16, 19), <strong>sfide</strong> e <strong>cicli di vita</strong>.","g.num.li6":"<strong>Anno personale</strong>: il tema del tuo anno in corso.","g.astro.h2":"3. Astrologia & oroscopo","g.astro.ou":"Scheda «Oroscopo»","g.astro.li1":"<strong>Segno solare</strong> e <strong>ascendente</strong> (calcolato astronomicamente a partire dalla tua ora e dal tuo luogo di nascita).","g.astro.li2":"<strong>Oroscopo del giorno</strong> e della <strong>settimana</strong>, per ambiti.","g.astro.li3":"<strong>Giorni favorevoli</strong> del mese.","g.astro.li4":"<strong>Compatibilità</strong> rapida tra segni.","g.astro.p1":"Per la <strong>ruota del tuo tema</strong> (i tuoi 12 segni in cerchio con Sole e Ascendente), usa il riquadro <em>Ruota del tema</em> nella home.","g.synth.h2":"4. Sintesi","g.synth.ou":"Scheda «Sintesi»","g.synth.p1":"Una lettura d'insieme che collega i tuoi tre pilastri: <strong>Sole × Ascendente × sentiero di vita</strong>, con la combinazione dei tuoi <strong>elementi</strong> dominanti (fuoco, terra, aria, acqua) e il filo conduttore della tua personalità.","g.profils.h2":"5. I miei profili","g.profils.ou":"Home → riquadro «I miei profili» 👪","g.profils.p1":"Registra le persone e gli animali della tua cerchia:","g.profils.li1":"<strong>Aggiungere una persona</strong>: nome, tipo di relazione (partner, figlio/a, genitore, fratello/sorella, amico/a, collega…), data, ora e luogo di nascita, e una <strong>foto</strong>.","g.profils.li2":"<strong>Modificare</strong> (✎) o <strong>eliminare</strong> (🗑) un profilo in qualsiasi momento.","g.profils.li3":"Tocca una persona per vedere la sua <strong>scheda completa</strong>: segno, ascendente, sentiero di vita e i suoi numeri — poi accedi alla vostra compatibilità.","g.compat.h2":"6. Compatibilità","g.compat.ou":"Home → «Compatibilità», o da un profilo","g.compat.p1":"Confronta il tuo tema con quello di una persona cara su <strong>8 dimensioni</strong> valutate, con barre di avanzamento: amore, passione, amicizia, comunicazione, lavoro, valori, quotidianità, stabilità — oltre ai tuoi <strong>punti di forza</strong> e ai tuoi <strong>punti di attenzione</strong>. La lista delle tue persone care è <strong>ordinata per punteggio</strong> in «I miei profili».","g.animaux.h2":"7. Animali della famiglia","g.animaux.ou":"«I miei profili» → Aggiungi un animale, o riquadro Animali 🐾","g.animaux.p1":"La numerologia funziona anche per i tuoi compagni! Registra un animale (nome, specie, data, foto) e toccalo per vedere la sua <strong>scheda numerologica</strong>: il suo numero, il suo carattere e un consiglio. (Nessun oroscopo per gli animali: la numerologia basta.)","g.bio.h2":"8. Bioritmi","g.bio.ou":"Home → riquadro «Bioritmi» 📈","g.bio.p1":"I tuoi tre cicli del giorno — <strong>fisico</strong> (23 gg), <strong>emotivo</strong> (28 gg), <strong>intellettuale</strong> (33 gg) — contati dalla tua nascita, con i <strong>giorni critici</strong> e una curva dei prossimi giorni.","g.prev.h2":"9. Previsioni & calendario","g.prev.ou":"Home → riquadri «Previsioni» 📅 e «Calendario»","g.prev.li1":"<strong>Previsioni</strong>: la vibrazione di ciascuno dei tuoi 12 prossimi mesi e il suo numero di giorni propizi.","g.prev.li2":"<strong>Calendario</strong>: la griglia del mese con ogni giorno colorato (propizio, riposo, numero maestro).","g.ciel.h2":"10. Il cielo del momento","g.ciel.ou":"Home → riquadro «Cielo del momento» 🌌","g.ciel.p1":"Ciò che accade nel cielo oggi: <strong>fase e segno della Luna</strong>, periodo di <strong>Mercurio retrogrado</strong>, e il <strong>numero universale</strong> del giorno, condiviso da tutti.","g.guid.h2":"11. Guida & diario","g.guid.ou":"Scheda «Guida» · Diario nella home","g.guid.li1":"<strong>Guida</strong>: rispondi a un breve questionario di vita e ricevi una lettura personalizzata, ambito per ambito (amore, lavoro, denaro, salute, spiritualità) in base al tuo anno personale.","g.guid.li2":"<strong>Diario</strong>: annota la risonanza delle tue giornate (da 1 a 5). Il riquadro <em>Tendenze</em> mostra l'evoluzione nel tempo.","g.carte.h2":"12. Carta del giorno & condivisione","g.carte.ou":"Home → riquadro «Carta del giorno» 🎴","g.carte.p1":"Una bella immagine della tua giornata (numero del giorno, segno, luna) pronta da condividere con le persone care. Un pulsante <em>Condividi la mia giornata</em> permette anche una rapida condivisione testuale.","g.pdf.h2":"13. Report PDF completo","g.pdf.ou":"Ruota delle Impostazioni ⚙︎ → «Report completo (PDF)»","g.pdf.p1":"Esporta tutto il tuo tema (numerologia, astrologia, sintesi, anno personale) in un elegante documento PDF da conservare o condividere.","g.outils.h2":"14. Strumenti","g.outils.ou":"Home → riquadro «Strumenti» 🧰","g.outils.li1":"<strong>Data favorevole</strong>: i giorni migliori in arrivo secondo un'intenzione (avviare, amare, decidere…).","g.outils.li2":"<strong>Nome / nome d'uso</strong>: prova la vibrazione di un nome o di uno pseudonimo.","g.outils.li3":"<strong>Indirizzo / numero</strong>: il numero di un luogo o di un numero civico.","g.decouvrir.h2":"15. Scopri","g.decouvrir.ou":"Home → riquadro «Scopri» 📖","g.decouvrir.p1":"Una sezione didattica che spiega in modo semplice tutto ciò che l'app calcola: i numeri, i cicli, la griglia di inclusione, l'astrologia, la sintesi. Ideale per iniziare.","g.widget.h2":"16. Widget schermata home (Android)","g.widget.ou":"Schermata home del telefono","g.widget.p1":"Metti il tuo <strong>numero del giorno</strong> direttamente sulla schermata home: tieni premuto sulla schermata home → <strong>Widget</strong> → <strong>Numerocoon</strong>, poi trascina il widget. Un tocco lo apre nell'app.","g.reglages.h2":"17. Impostazioni","g.reglages.ou":"Ruota dentata ⚙︎ in alto a destra","g.reglages.li1":"<strong>Lingua</strong>: 9 lingue (francese, inglese, tedesco, italiano, portoghese, spagnolo, svedese, norvegese, finlandese).","g.reglages.li2":"<strong>Dimensione del testo</strong>: piccola / normale / grande.","g.reglages.li3":"<strong>Promemoria quotidiano</strong>: una notifica all'ora che preferisci.","g.reglages.li4":"<strong>Backup & ripristino</strong>: esporta i tuoi dati in un file e ripristinali su un altro dispositivo (tutto resta in locale).","g.maj.h2":"18. Aggiornamenti","g.maj.ou":"Automatico · Impostazioni ⚙︎ → «Aggiornamenti»","g.maj.p1":"All'avvio, l'app verifica se esiste una versione più recente e ti propone di scaricarla. Puoi anche verificare manualmente dalle Impostazioni. I tuoi dati vengono conservati da una versione all'altra.","g.conf.h2":"19. Privacy","g.conf.ou":"—","g.conf.p1":"Numerocoon non raccoglie <strong>alcun dato</strong>: nessun account, nessuna pubblicità, nessun tracciatore. Tutto ciò che inserisci resta sul tuo dispositivo. Dettagli nella <a href=\"privacy.html\">politica sulla privacy</a>.","g.conf.astuce":"Numerocoon propone un supporto di introspezione e benessere fondato su tradizioni simboliche. Non è né una previsione, né un parere medico, finanziario o legale.","g.footer.line":"<strong>Numerocoon</strong> — di Bengacoon · <a href=\"index.html\">Home</a> · <a href=\"privacy.html\">Privacy</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Politica sulla privacy — Numerocoon","priv.hero.title":"Politica sulla privacy","priv.hero.date":"Ultimo aggiornamento: 1 settembre 2026 · Editore: Bengacoon","priv.summary":"<strong>In sintesi:</strong> Numerocoon non raccoglie, non trasmette e non condivide\n    <strong>alcun dato personale</strong>. Non c'è né un account online, né pubblicità, né tracciatori,\n    né strumenti di misurazione dell'audience. Tutto ciò che inserisci resta <strong>unicamente sul tuo\n    dispositivo</strong>. L'unica connessione a Internet serve a verificare se esiste un aggiornamento\n    dell'applicazione — <em>nessuna informazione che ti riguarda viene inviata</em>.","priv.s1.h2":"1. Chi siamo","priv.s1.p1":"Numerocoon è un'applicazione di numerologia e oroscopo del benessere, pubblicata nell'ambito\n  dell'universo Bengacoon. Domande: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Dati che raccogliamo","priv.s2.p1":"<strong>Nessuno.</strong> Non raccogliamo alcun dato personale. L'applicazione non crea\n  alcun account su un server, non ti identifica, e non contiene né pubblicità, né tracciatori, né\n  strumenti di analisi.","priv.s3.h2":"3. Dati registrati sul tuo dispositivo","priv.s3.intro":"Per funzionare, l'applicazione registra alcune informazioni localmente, solo sul tuo\n  telefono (mai su un server):","priv.s3.li1":"il tuo profilo: nome, cognome ed e-mail eventuali;","priv.s3.li2":"i tuoi dati di nascita: data, ora e luogo (per il tema e l'ascendente);","priv.s3.li3":"le persone care e gli animali che registri (nome, dati di nascita, foto);","priv.s3.li4":"le tue risposte al questionario di guida e le note del tuo diario;","priv.s3.li5":"le tue preferenze: lingua, dimensione del testo, ora del promemoria quotidiano.","priv.s3.outro":"Questi dati non lasciano mai il tuo dispositivo e non ci vengono mai trasmessi.","priv.s4.h2":"4. Permessi e accesso alla rete","priv.s4.li1":"<strong>Notifiche</strong>: unicamente per il promemoria quotidiano che attivi.","priv.s4.li2":"<strong>Foto</strong>: unicamente se aggiungi una foto a un profilo; l'immagine resta sul tuo dispositivo.","priv.s4.li3":"<strong>Internet</strong>: unicamente per <strong>verificare l'esistenza di un aggiornamento</strong>. <strong>Nessun dato che ti riguarda viene inviato.</strong>","priv.s4.p1":"L'applicazione non richiede l'accesso alla posizione, ai contatti, al microfono o alla fotocamera.\n  Il luogo di nascita viene scelto da una lista integrata.","priv.s5.h2":"5. Condivisione con terzi","priv.s5.p1":"Nessuna. La condivisione («Condividi la mia giornata», carta del giorno, backup, PDF) utilizza la condivisione\n  del tuo sistema: il contenuto viene trasmesso solo all'applicazione che <em>tu</em> scegli. La\n  verifica dell'aggiornamento contatta GitHub, che tecnicamente può registrare l'indirizzo IP all'origine\n  della richiesta; noi non vi abbiamo accesso.","priv.s6.h2":"6. Conservazione ed eliminazione","priv.s6.p1":"I tuoi dati restano sul tuo dispositivo finché lo desideri. Puoi esportarli,\n  ripristinarli, cancellarli dalle Impostazioni, o eliminare tutto disinstallando l'applicazione.","priv.s7.h2":"7. Minori","priv.s7.p1":"L'applicazione non si rivolge in particolare ai minori e non raccoglie alcun dato che li\n  riguardi.","priv.s8.h2":"8. Avvertenza sul benessere","priv.s8.p1":"Numerocoon propone un supporto di introspezione e benessere fondato su tradizioni\n  simboliche. Non è né una previsione, né un dispositivo medico, né un parere finanziario o\n  legale.","priv.footer":"<strong>Numerocoon</strong> — di Bengacoon · <a href=\"index.html\">Home</a> ·\n    <a href=\"guide.html\">Guida</a> · © 2026 Bengacoon<br>\n    Contatto: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Tema e lingua","idx.ver.v210.desc":"Scegli l’aspetto: sfondo chiaro o scuro, o come il tuo telefono. E l’interfaccia è ora completamente tradotta, fino alle impostazioni."},"pt":{"idx.meta.title":"Numerocoon — Numerologia & horóscopo de bem-estar","idx.meta.desc":"Numerocoon, por Bengacoon: o seu mapa numerológico detalhado, o seu ascendente calculado a partir da hora de nascimento, horóscopo, compatibilidade e orientação. Gratuito, em 9 idiomas.","brand.by":"por Bengacoon","nav.home":"Início","nav.features":"Funções","nav.guide":"Guia","nav.privacy":"Privacidade","idx.hero.lead":"Numerologia & horóscopo reunidos. A partir da sua data, hora e local de nascimento, descubra o seu mapa, o seu ascendente e uma orientação que se parece consigo.","idx.store.android":"<small>Android · APK direto</small>Descarregar","idx.store.play":"<small>Brevemente na</small>Google&nbsp;Play","idx.store.ios":"<small>Brevemente na</small>App&nbsp;Store","idx.func.eyebrow":"O que a app faz","idx.func.h2":"Um retrato completo, com suavidade","idx.func.sub":"Compreenda os seus números, leia o seu céu e avance dia após dia — sem conta, sem jargão.","idx.card.numero.h3":"Numerologia detalhada","idx.card.numero.p":"Caminho de vida, expressão, alma, personalidade, desafios e ciclos, grade de inclusão e dívidas kármicas. Até à parte de sombra de cada número, para um retrato honesto.","idx.card.ascendant.h3":"Ascendente & horóscopo","idx.card.ascendant.p":"O seu signo solar e o seu ascendente, calculado astronomicamente a partir da hora e do local de nascimento. Horóscopo do dia, da semana e dias favoráveis.","idx.card.synthese.h3":"Síntese","idx.card.synthese.p":"Uma leitura que liga tudo: Sol × Ascendente × caminho de vida, e a combinação dos seus elementos dominantes — fogo, terra, ar, água.","idx.card.compat.h3":"Compatibilidade detalhada","idx.card.compat.p":"Guarde os seus entes queridos e compare os vossos mapas em 8 dimensões avaliadas — amor, paixão, amizade, comunicação, trabalho, valores, quotidiano, estabilidade — com pontos fortes e pontos de atenção.","idx.card.guidance.h3":"Orientação & diário","idx.card.guidance.p":"Um questionário de vida e, depois, uma orientação personalizada área a área conforme o seu ano pessoal. Um diário para anotar a ressonância dos seus dias.","idx.card.rappel.h3":"Lembrete & partilha","idx.card.rappel.p":"Um lembrete diário à hora que escolher para não perder nada, e a partilha do seu dia num gesto, quando quiser.","idx.free.price":"100% gratuito","idx.free.h2":"Tudo é oferecido, sem publicidade","idx.free.sub":"Nenhuma compra, nenhuma subscrição, nenhuma função bloqueada.","idx.free.li1":"Mapa numerológico completo","idx.free.li2":"Ascendente, horóscopo e dias favoráveis","idx.free.li3":"Síntese, compatibilidade e orientação","idx.free.li4":"Diário, lembretes e partilha","idx.free.note":"O Numerocoon é um presente da galáxia Bengacoon — para descobrir em total liberdade.","idx.lang.eyebrow":"Para toda a gente","idx.lang.h2":"Disponível em 9 idiomas","idx.lang.sub":"A aplicação está totalmente traduzida, até aos textos de orientação.","idx.ver.eyebrow":"Sempre em movimento","idx.ver.h2":"As últimas versões","idx.ver.sub":"O Numerocoon evolui regularmente — eis as novidades recentes. O histórico completo está no GitHub.","idx.ver.v1.label":"Ficha do animal","idx.ver.v1.desc":"A ficha de um animal é bem mais completa: forças, necessidades, lugar na família, palavra carinhosa e energia do dia.","idx.ver.v2.label":"Ícone & guia","idx.ver.v2.desc":"Novo ícone (medalhão de ouro, crescente de lua) e um guia de utilização completo integrado, acessível offline.","idx.ver.v3.label":"Fichas & fotos","idx.ver.v3.desc":"Uma foto em cada perfil, a ficha completa de uma pessoa (signo, ascendente, números) e a ficha numerológica dos animais.","idx.ver.v4.label":"Perfis & animais","idx.ver.v4.desc":"Faça a gestão de vários perfis (cônjuge, filhos, família…) com adição/edição/eliminação e lista de compatibilidade, além de perfis para os seus animais.","idx.ver.v5.label":"Calendário & céu","idx.ver.v5.desc":"Calendário numerológico do mês, «céu do momento» (Lua, Mercúrio retrógrado, número universal) e numerologia do seu animal de estimação.","idx.ver.v6.label":"Widget de ecrã inicial","idx.ver.v6.desc":"Um widget Android para colocar o seu número do dia diretamente no ecrã inicial do telemóvel.","idx.ver.v7.label":"Carta, roda & previsões","idx.ver.v7.desc":"Carta do dia para partilhar, roda do mapa (Sol + Ascendente), previsões a 12 meses, tendências do diário, cópia de segurança/restauro, tamanho de texto ajustável e visita de boas-vindas.","idx.ver.v8.label":"Atualizações diretas","idx.ver.v8.desc":"A versão APK direta descarrega e instala agora as suas atualizações a partir da aplicação, sem passar pelo navegador.","idx.ver.v9.label":"Biorritmos & PDF","idx.ver.v9.desc":"Biorritmos do dia (físico, emocional, intelectual), secção «Descobrir» para compreender tudo, e exportação do mapa completo em PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Alinhamento das versões iOS e Android e preparação da publicação nas duas plataformas.","idx.ver.v11.label":"Definições &amp; marca","idx.ver.v11.desc":"Roda dentada de acesso às Definições e assinatura «por Bengacoon» no ecrã inicial.","idx.ver.v12.label":"100% traduzido","idx.ver.v12.desc":"Localização completa, até às frases montadas, nos 9 idiomas.","idx.ver.more":"Ver todo o histórico de versões →","idx.priv.eyebrow":"Os seus dados, consigo","idx.priv.h2":"Nada sai do seu telemóvel","idx.priv.sub":"Nenhuma conta a criar, nenhum dado pessoal recolhido. O seu perfil e os seus entes queridos permanecem no seu dispositivo. A única ligação serve para verificar as atualizações — sem enviar nada que lhe diga respeito.","idx.footer":"<strong>Numerocoon</strong> — por Bengacoon · Disponível em 9 idiomas<br>\n    <a href=\"guide.html\">Guia de utilização</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Política de privacidade</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">O Numerocoon oferece um apoio de introspeção e de bem-estar baseado em tradições simbólicas (numerologia, astrologia). Não é uma previsão, nem um dispositivo médico, nem um parecer financeiro ou jurídico, e não substitui o parecer de um profissional qualificado.</p>","g.meta.title":"Guia de utilização — Numerocoon","g.meta.desc":"O guia completo do Numerocoon: tudo o que pode fazer (numerologia, ascendente, horóscopo, compatibilidade, perfis, biorritmos…) e como.","g.hero.h1":"Guia de utilização","g.hero.p":"Tudo o que pode fazer com o Numerocoon, e como. A aplicação está em 9 idiomas; este guia está em português.","g.toc.title":"Índice","g.toc.1":"1. Começar","g.toc.2":"2. Numerologia","g.toc.3":"3. Astrologia","g.toc.4":"4. Síntese","g.toc.5":"5. Os meus perfis","g.toc.6":"6. Compatibilidade","g.toc.7":"7. Animais","g.toc.8":"8. Biorritmos","g.toc.9":"9. Previsões & calendário","g.toc.10":"10. O céu do momento","g.toc.11":"11. Orientação & diário","g.toc.12":"12. Carta & partilha","g.toc.13":"13. Relatório PDF","g.toc.14":"14. Ferramentas","g.toc.15":"15. Descobrir","g.toc.16":"16. Widget","g.toc.17":"17. Definições","g.toc.18":"18. Atualizações","g.toc.19":"19. Privacidade","g.intro.note":"Cada secção indica <strong style=\"color:var(--amethyste)\">onde a encontrar</strong> na aplicação (separador em baixo, roda das Definições no canto superior direito, ou mosaicos de acesso rápido do ecrã inicial).","g.demarrer.h2":"1. Começar — criar o seu perfil","g.demarrer.ou":"Na primeira abertura","g.demarrer.p1":"Ao iniciar, o Numerocoon pede-lhe que crie o seu perfil. Preencha:","g.demarrer.li1":"<strong>Nome próprio</strong> (obrigatório), apelido e e-mail facultativos;","g.demarrer.li2":"<strong>Data de nascimento</strong> (dia, mês, ano);","g.demarrer.li3":"<strong>Hora de nascimento</strong> e <strong>local</strong> — necessários para calcular o seu <em>ascendente</em> (facultativos, mas recomendados).","g.demarrer.astuce":"🔒 Tudo permanece no seu dispositivo: nenhuma conta online, nenhum dado enviado. Uma visita de boas-vindas apresenta-lhe a app no primeiro arranque.","g.num.h2":"2. Numerologia","g.num.ou":"Separador «Numerologia»","g.num.p1":"O seu mapa numerológico pitagórico completo:","g.num.li1":"<strong>Caminho de vida</strong>: o seu número principal, com o seu retrato (forças, desafios, no amor, no trabalho, conselho).","g.num.li2":"<strong>Parte de sombra</strong>: a face oculta do seu número e a sua afirmação.","g.num.li3":"<strong>Números do nome</strong>: expressão, alma, personalidade, ativo, hereditário, número de nascimento.","g.num.li4":"<strong>Grade de inclusão</strong>: os seus trunfos e as suas lições a partir do seu nome.","g.num.li5":"<strong>Dívidas kármicas</strong> (13, 14, 16, 19), <strong>desafios</strong> e <strong>ciclos de vida</strong>.","g.num.li6":"<strong>Ano pessoal</strong>: o tema do seu ano atual.","g.astro.h2":"3. Astrologia & horóscopo","g.astro.ou":"Separador «Horóscopo»","g.astro.li1":"<strong>Signo solar</strong> e <strong>ascendente</strong> (calculado astronomicamente a partir da sua hora e local de nascimento).","g.astro.li2":"<strong>Horóscopo do dia</strong> e da <strong>semana</strong>, por áreas.","g.astro.li3":"<strong>Dias favoráveis</strong> do mês.","g.astro.li4":"<strong>Compatibilidade</strong> rápida entre signos.","g.astro.p1":"Para a <strong>roda do seu mapa</strong> (os seus 12 signos em círculo com Sol e Ascendente), utilize o mosaico <em>Roda do mapa</em> no ecrã inicial.","g.synth.h2":"4. Síntese","g.synth.ou":"Separador «Síntese»","g.synth.p1":"Uma leitura de conjunto que liga os seus três pilares: <strong>Sol × Ascendente × caminho de vida</strong>, com a combinação dos seus <strong>elementos</strong> dominantes (fogo, terra, ar, água) e o fio condutor da sua personalidade.","g.profils.h2":"5. Os meus perfis","g.profils.ou":"Início → mosaico «Os meus perfis» 👪","g.profils.p1":"Guarde as pessoas e os animais à sua volta:","g.profils.li1":"<strong>Adicionar uma pessoa</strong>: nome próprio, tipo de relação (cônjuge, filho(a), progenitor, irmão/irmã, amigo(a), colega…), data, hora e local de nascimento, e uma <strong>foto</strong>.","g.profils.li2":"<strong>Editar</strong> (✎) ou <strong>eliminar</strong> (🗑) um perfil a qualquer momento.","g.profils.li3":"Toque numa pessoa para ver a sua <strong>ficha completa</strong>: signo, ascendente, caminho de vida e os seus números — e depois aceda à sua compatibilidade.","g.compat.h2":"6. Compatibilidade","g.compat.ou":"Início → «Compatibilidade», ou a partir de um perfil","g.compat.p1":"Compare o seu mapa com o de um ente querido em <strong>8 dimensões</strong> avaliadas, com barras de progresso: amor, paixão, amizade, comunicação, trabalho, valores, quotidiano, estabilidade — além dos seus <strong>pontos fortes</strong> e dos seus <strong>pontos de atenção</strong>. A lista dos seus entes queridos está <strong>ordenada por pontuação</strong> em «Os meus perfis».","g.animaux.h2":"7. Animais da família","g.animaux.ou":"«Os meus perfis» → Adicionar um animal, ou mosaico Animais 🐾","g.animaux.p1":"A numerologia também funciona para os seus companheiros! Guarde um animal (nome, espécie, data, foto) e toque-lhe para ver a sua <strong>ficha numerológica</strong>: o seu número, o seu carácter e um conselho. (Sem horóscopo para os animais: a numerologia basta.)","g.bio.h2":"8. Biorritmos","g.bio.ou":"Início → mosaico «Biorritmos» 📈","g.bio.p1":"Os seus três ciclos do dia — <strong>físico</strong> (23 d), <strong>emocional</strong> (28 d), <strong>intelectual</strong> (33 d) — contados desde o seu nascimento, com os <strong>dias críticos</strong> e uma curva dos próximos dias.","g.prev.h2":"9. Previsões & calendário","g.prev.ou":"Início → mosaicos «Previsões» 📅 e «Calendário»","g.prev.li1":"<strong>Previsões</strong>: a vibração de cada um dos seus próximos 12 meses e o seu número de dias favoráveis.","g.prev.li2":"<strong>Calendário</strong>: a grelha do mês com cada dia colorido (favorável, descanso, número mestre).","g.ciel.h2":"10. O céu do momento","g.ciel.ou":"Início → mosaico «Céu do momento» 🌌","g.ciel.p1":"O que se passa no céu hoje: <strong>fase e signo da Lua</strong>, período de <strong>Mercúrio retrógrado</strong>, e o <strong>número universal</strong> do dia, partilhado por todos.","g.guid.h2":"11. Orientação & diário","g.guid.ou":"Separador «Orientação» · Diário no ecrã inicial","g.guid.li1":"<strong>Orientação</strong>: responda a um breve questionário de vida e receba uma leitura personalizada, área a área (amor, trabalho, dinheiro, saúde, espiritualidade) conforme o seu ano pessoal.","g.guid.li2":"<strong>Diário</strong>: anote a ressonância dos seus dias (1 a 5). O mosaico <em>Tendências</em> mostra a evolução ao longo do tempo.","g.carte.h2":"12. Carta do dia & partilha","g.carte.ou":"Início → mosaico «Carta do dia» 🎴","g.carte.p1":"Uma bela imagem do seu dia (número do dia, signo, lua) pronta a partilhar com os seus entes queridos. Um botão <em>Partilhar o meu dia</em> permite também uma partilha rápida por texto.","g.pdf.h2":"13. Relatório PDF completo","g.pdf.ou":"Roda das Definições ⚙︎ → «Relatório completo (PDF)»","g.pdf.p1":"Exporte todo o seu mapa (numerologia, astrologia, síntese, ano pessoal) num elegante documento PDF para guardar ou partilhar.","g.outils.h2":"14. Ferramentas","g.outils.ou":"Início → mosaico «Ferramentas» 🧰","g.outils.li1":"<strong>Data favorável</strong>: os melhores dias por vir conforme uma intenção (lançar, amar, decidir…).","g.outils.li2":"<strong>Nome próprio / nome de uso</strong>: teste a vibração de um nome ou de um pseudónimo.","g.outils.li3":"<strong>Morada / número</strong>: o número de um local ou de um número.","g.decouvrir.h2":"15. Descobrir","g.decouvrir.ou":"Início → mosaico «Descobrir» 📖","g.decouvrir.p1":"Uma secção pedagógica que explica de forma simples tudo o que a app calcula: os números, os ciclos, a grade de inclusão, a astrologia, a síntese. Ideal para começar.","g.widget.h2":"16. Widget do ecrã inicial (Android)","g.widget.ou":"Ecrã inicial do telemóvel","g.widget.p1":"Coloque o seu <strong>número do dia</strong> diretamente no ecrã inicial: mantenha premido o ecrã inicial → <strong>Widgets</strong> → <strong>Numerocoon</strong>, e depois arraste o widget. Um toque abre-o na app.","g.reglages.h2":"17. Definições","g.reglages.ou":"Roda dentada ⚙︎ no canto superior direito","g.reglages.li1":"<strong>Idioma</strong>: 9 idiomas (francês, inglês, alemão, italiano, português, espanhol, sueco, norueguês, finlandês).","g.reglages.li2":"<strong>Tamanho do texto</strong>: pequeno / normal / grande.","g.reglages.li3":"<strong>Lembrete diário</strong>: uma notificação à hora que escolher.","g.reglages.li4":"<strong>Cópia de segurança & restauro</strong>: exporte os seus dados para um ficheiro e restaure-os noutro dispositivo (tudo permanece local).","g.maj.h2":"18. Atualizações","g.maj.ou":"Automático · Definições ⚙︎ → «Atualizações»","g.maj.p1":"Ao iniciar, a app verifica se existe uma versão mais recente e propõe-lhe descarregá-la. Também pode verificar manualmente a partir das Definições. Os seus dados são conservados de uma versão para a outra.","g.conf.h2":"19. Privacidade","g.conf.ou":"—","g.conf.p1":"O Numerocoon não recolhe <strong>nenhum dado</strong>: sem conta, sem publicidade, sem rastreador. Tudo o que introduz permanece no seu dispositivo. Detalhes na <a href=\"privacy.html\">política de privacidade</a>.","g.conf.astuce":"O Numerocoon oferece um apoio de introspeção e de bem-estar baseado em tradições simbólicas. Não é uma previsão, nem um parecer médico, financeiro ou jurídico.","g.footer.line":"<strong>Numerocoon</strong> — por Bengacoon · <a href=\"index.html\">Início</a> · <a href=\"privacy.html\">Privacidade</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Política de privacidade — Numerocoon","priv.hero.title":"Política de privacidade","priv.hero.date":"Última atualização: 1 de setembro de 2026 · Editor: Bengacoon","priv.summary":"<strong>Em resumo:</strong> o Numerocoon não recolhe, não transmite e não partilha\n    <strong>nenhum dado pessoal</strong>. Não há conta online, nem publicidade, nem rastreador,\n    nem ferramenta de medição de audiência. Tudo o que introduz permanece <strong>unicamente no seu\n    dispositivo</strong>. A única ligação à Internet serve para verificar se existe uma atualização da\n    aplicação — <em>nenhuma informação que lhe diga respeito é enviada</em>.","priv.s1.h2":"1. Quem somos","priv.s1.p1":"O Numerocoon é uma aplicação de numerologia e horóscopo de bem-estar, editada no âmbito\n  do universo Bengacoon. Questões: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Dados que recolhemos","priv.s2.p1":"<strong>Nenhum.</strong> Não recolhemos qualquer dado pessoal. A aplicação não cria\n  nenhuma conta num servidor, não o identifica, e não contém publicidade, nem rastreador, nem\n  ferramenta de análise.","priv.s3.h2":"3. Dados guardados no seu dispositivo","priv.s3.intro":"Para funcionar, a aplicação guarda certas informações localmente, apenas no seu\n  telemóvel (nunca num servidor):","priv.s3.li1":"o seu perfil: nome próprio, apelido e e-mail eventuais;","priv.s3.li2":"os seus dados de nascimento: data, hora e local (para o mapa e o ascendente);","priv.s3.li3":"os entes queridos e animais que guarda (nome, dados de nascimento, foto);","priv.s3.li4":"as suas respostas ao questionário de orientação e as notas do seu diário;","priv.s3.li5":"as suas preferências: idioma, tamanho do texto, hora do lembrete diário.","priv.s3.outro":"Estes dados nunca saem do seu dispositivo e nunca nos são transmitidos.","priv.s4.h2":"4. Permissões e acesso à rede","priv.s4.li1":"<strong>Notificações</strong>: unicamente para o lembrete diário que ativa.","priv.s4.li2":"<strong>Fotos</strong>: unicamente se adicionar uma foto a um perfil; a imagem permanece no seu dispositivo.","priv.s4.li3":"<strong>Internet</strong>: unicamente para <strong>verificar a existência de uma atualização</strong>. <strong>Nenhum dado que lhe diga respeito é enviado.</strong>","priv.s4.p1":"A aplicação não pede acesso à localização, aos contactos, ao microfone ou à câmara.\n  O local de nascimento é escolhido numa lista integrada.","priv.s5.h2":"5. Partilha com terceiros","priv.s5.p1":"Nenhuma. A partilha («Partilhar o meu dia», carta do dia, cópia de segurança, PDF) utiliza a partilha\n  do seu sistema: o conteúdo só é transmitido à aplicação que <em>você</em> escolhe. A\n  verificação de atualização contacta o GitHub, que pode tecnicamente registar o endereço IP na\n  origem do pedido; nós não temos acesso a isso.","priv.s6.h2":"6. Conservação e eliminação","priv.s6.p1":"Os seus dados permanecem no seu dispositivo enquanto quiser. Pode exportá-los,\n  restaurá-los, apagá-los a partir das Definições, ou eliminar tudo desinstalando a aplicação.","priv.s7.h2":"7. Crianças","priv.s7.p1":"A aplicação não se dirige particularmente às crianças e não recolhe qualquer dado que lhes\n  diga respeito.","priv.s8.h2":"8. Aviso de bem-estar","priv.s8.p1":"O Numerocoon oferece um apoio de introspeção e de bem-estar baseado em tradições\n  simbólicas. Não é uma previsão, nem um dispositivo médico, nem um parecer financeiro ou\n  jurídico.","priv.footer":"<strong>Numerocoon</strong> — por Bengacoon · <a href=\"index.html\">Início</a> ·\n    <a href=\"guide.html\">Guia</a> · © 2026 Bengacoon<br>\n    Contacto: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Tema e idioma","idx.ver.v210.desc":"Escolha o aspeto: fundo claro ou escuro, ou de acordo com o seu telemóvel. E a interface está agora totalmente traduzida, até às definições."},"es":{"idx.meta.title":"Numerocoon — Numerología y horóscopo de bienestar","idx.meta.desc":"Numerocoon, de Bengacoon: tu carta numerológica detallada, tu ascendente calculado a partir de la hora de nacimiento, horóscopo, compatibilidad y orientación. Gratis, en 9 idiomas.","brand.by":"de Bengacoon","nav.home":"Inicio","nav.features":"Funciones","nav.guide":"Guía","nav.privacy":"Privacidad","idx.hero.lead":"Numerología y horóscopo reunidos. A partir de tu fecha, hora y lugar de nacimiento, descubre tu carta, tu ascendente y una orientación que se parece a ti.","idx.store.android":"<small>Android · APK directo</small>Descargar","idx.store.play":"<small>Próximamente en</small>Google&nbsp;Play","idx.store.ios":"<small>Próximamente en</small>App&nbsp;Store","idx.func.eyebrow":"Lo que hace la app","idx.func.h2":"Un retrato completo, con delicadeza","idx.func.sub":"Comprende tus números, lee tu cielo y avanza día tras día, sin cuenta y sin tecnicismos.","idx.card.numero.h3":"Numerología detallada","idx.card.numero.p":"Camino de vida, expresión, alma, personalidad, retos y ciclos, tabla de inclusión y deudas kármicas. Hasta la sombra de cada número, para un retrato honesto.","idx.card.ascendant.h3":"Ascendente y horóscopo","idx.card.ascendant.p":"Tu signo solar y tu ascendente, calculado astronómicamente a partir de la hora y el lugar de nacimiento. Horóscopo del día, de la semana y días favorables.","idx.card.synthese.h3":"Síntesis","idx.card.synthese.p":"Una lectura que lo conecta todo: Sol × Ascendente × camino de vida, y la combinación de tus elementos dominantes: fuego, tierra, aire, agua.","idx.card.compat.h3":"Compatibilidad detallada","idx.card.compat.p":"Guarda a tus seres queridos y compara vuestras cartas en 8 dimensiones puntuadas: amor, pasión, amistad, comunicación, trabajo, valores, día a día, estabilidad, con fortalezas y puntos de atención.","idx.card.guidance.h3":"Orientación y diario","idx.card.guidance.p":"Un cuestionario de vida y, después, una orientación personalizada área por área según tu año personal. Un diario para anotar la resonancia de tus días.","idx.card.rappel.h3":"Recordatorio y compartir","idx.card.rappel.p":"Un recordatorio diario a la hora que elijas para no perderte nada, y la posibilidad de compartir tu día con un gesto, cuando quieras.","idx.free.price":"100 % gratis","idx.free.h2":"Todo está incluido, sin publicidad","idx.free.sub":"Sin compras, sin suscripción, sin funciones bloqueadas.","idx.free.li1":"Carta numerológica completa","idx.free.li2":"Ascendente, horóscopo y días favorables","idx.free.li3":"Síntesis, compatibilidad y orientación","idx.free.li4":"Diario, recordatorios y compartir","idx.free.note":"Numerocoon es un regalo de la galaxia Bengacoon, para descubrir con total libertad.","idx.lang.eyebrow":"Para todo el mundo","idx.lang.h2":"Disponible en 9 idiomas","idx.lang.sub":"La aplicación está totalmente traducida, hasta los textos de orientación.","idx.ver.eyebrow":"Siempre en movimiento","idx.ver.h2":"Las últimas versiones","idx.ver.sub":"Numerocoon evoluciona con regularidad: aquí tienes las novedades recientes. El historial completo está en GitHub.","idx.ver.v1.label":"Ficha animal","idx.ver.v1.desc":"La ficha de un animal es mucho más completa: fortalezas, necesidades, lugar en la familia, palabra tierna y energía del día.","idx.ver.v2.label":"Icono y guía","idx.ver.v2.desc":"Nuevo icono (medallón de oro, luna creciente) y una guía de uso completa integrada, accesible sin conexión.","idx.ver.v3.label":"Fichas y fotos","idx.ver.v3.desc":"Una foto en cada perfil, la ficha completa de una persona (signo, ascendente, números) y la ficha numerológica de los animales.","idx.ver.v4.label":"Perfiles y animales","idx.ver.v4.desc":"Gestiona varios perfiles (pareja, hijos, familia…) con añadir/editar/eliminar y lista de compatibilidad, además de perfiles para tus animales.","idx.ver.v5.label":"Calendario y cielo","idx.ver.v5.desc":"Calendario numerológico del mes, «cielo del momento» (Luna, Mercurio retrógrado, número universal) y numerología de tu mascota.","idx.ver.v6.label":"Widget de inicio","idx.ver.v6.desc":"Un widget de Android para colocar tu número del día directamente en la pantalla de inicio de tu teléfono.","idx.ver.v7.label":"Carta, rueda y previsiones","idx.ver.v7.desc":"Carta del día para compartir, rueda de la carta (Sol + Ascendente), previsiones a 12 meses, tendencias del diario, copia de seguridad/restauración, tamaño de texto ajustable y recorrido de bienvenida.","idx.ver.v8.label":"Actualizaciones directas","idx.ver.v8.desc":"La versión APK directo ahora descarga e instala sus actualizaciones desde la propia aplicación, sin pasar por el navegador.","idx.ver.v9.label":"Biorritmos y PDF","idx.ver.v9.desc":"Biorritmos del día (físico, emocional, intelectual), sección «Descubrir» para entenderlo todo, y exportación de la carta completa en PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Alineación de las versiones de iOS y Android y preparación de la publicación en ambas plataformas.","idx.ver.v11.label":"Ajustes y marca","idx.ver.v11.desc":"Rueda dentada de acceso a los Ajustes y firma «de Bengacoon» en el inicio.","idx.ver.v12.label":"100 % traducido","idx.ver.v12.desc":"Localización completa, hasta las frases compuestas, en los 9 idiomas.","idx.ver.more":"Ver todo el historial de versiones →","idx.priv.eyebrow":"Tus datos, en tu casa","idx.priv.h2":"Nada sale de tu teléfono","idx.priv.sub":"Sin cuenta que crear, sin recopilación de datos personales. Tu perfil y tus seres queridos permanecen en tu dispositivo. La única conexión sirve para comprobar las actualizaciones, sin enviar nada sobre ti.","idx.footer":"<strong>Numerocoon</strong> — de Bengacoon · Disponible en 9 idiomas<br>\n    <a href=\"guide.html\">Guía de uso</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Política de privacidad</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon ofrece un apoyo de introspección y bienestar basado en tradiciones simbólicas (numerología, astrología). No es una predicción, ni un dispositivo médico, ni un consejo financiero o jurídico, y no sustituye la opinión de un profesional cualificado.</p>","g.meta.title":"Guía de uso — Numerocoon","g.meta.desc":"La guía completa de Numerocoon: todo lo que puedes hacer (numerología, ascendente, horóscopo, compatibilidad, perfiles, biorritmos…) y cómo.","g.hero.h1":"Guía de uso","g.hero.p":"Todo lo que puedes hacer con Numerocoon, y cómo. La aplicación está en 9 idiomas; esta guía está en español.","g.toc.title":"Índice","g.toc.1":"1. Empezar","g.toc.2":"2. Numerología","g.toc.3":"3. Astrología","g.toc.4":"4. Síntesis","g.toc.5":"5. Mis perfiles","g.toc.6":"6. Compatibilidad","g.toc.7":"7. Animales","g.toc.8":"8. Biorritmos","g.toc.9":"9. Previsiones y calendario","g.toc.10":"10. El cielo del momento","g.toc.11":"11. Orientación y diario","g.toc.12":"12. Carta y compartir","g.toc.13":"13. Informe PDF","g.toc.14":"14. Herramientas","g.toc.15":"15. Descubrir","g.toc.16":"16. Widget","g.toc.17":"17. Ajustes","g.toc.18":"18. Actualizaciones","g.toc.19":"19. Privacidad","g.intro.note":"Cada sección indica <strong style=\"color:var(--amethyste)\">dónde encontrarla</strong> en la aplicación (pestaña inferior, rueda de Ajustes arriba a la derecha, o mosaicos de acceso rápido del inicio).","g.demarrer.h2":"1. Empezar — crear tu perfil","g.demarrer.ou":"Al abrir por primera vez","g.demarrer.p1":"Al iniciarse, Numerocoon te pide crear tu perfil. Rellena:","g.demarrer.li1":"<strong>Nombre</strong> (obligatorio), apellido y correo electrónico opcionales;","g.demarrer.li2":"<strong>Fecha de nacimiento</strong> (día, mes, año);","g.demarrer.li3":"<strong>Hora de nacimiento</strong> y <strong>lugar</strong>, necesarios para calcular tu <em>ascendente</em> (opcionales, pero recomendados).","g.demarrer.astuce":"🔒 Todo permanece en tu dispositivo: sin cuenta en línea, sin datos enviados. Un recorrido de bienvenida te presenta la app al primer inicio.","g.num.h2":"2. Numerología","g.num.ou":"Pestaña «Numerología»","g.num.p1":"Tu carta numerológica pitagórica completa:","g.num.li1":"<strong>Camino de vida</strong>: tu número principal, con su retrato (fortalezas, retos, en el amor, en el trabajo, consejo).","g.num.li2":"<strong>Sombra</strong>: la cara oculta de tu número y su afirmación.","g.num.li3":"<strong>Números del nombre</strong>: expresión, alma, personalidad, activo, hereditario, número de nacimiento.","g.num.li4":"<strong>Tabla de inclusión</strong>: tus bazas y tus lecciones según tu nombre.","g.num.li5":"<strong>Deudas kármicas</strong> (13, 14, 16, 19), <strong>retos</strong> y <strong>ciclos de vida</strong>.","g.num.li6":"<strong>Año personal</strong>: el tema de tu año en curso.","g.astro.h2":"3. Astrología y horóscopo","g.astro.ou":"Pestaña «Horóscopo»","g.astro.li1":"<strong>Signo solar</strong> y <strong>ascendente</strong> (calculado astronómicamente a partir de tu hora y lugar de nacimiento).","g.astro.li2":"<strong>Horóscopo del día</strong> y de la <strong>semana</strong>, por áreas.","g.astro.li3":"<strong>Días favorables</strong> del mes.","g.astro.li4":"<strong>Compatibilidad</strong> rápida entre signos.","g.astro.p1":"Para la <strong>rueda de tu carta</strong> (tus 12 signos en círculo con Sol y Ascendente), usa el mosaico <em>Rueda de la carta</em> en el inicio.","g.synth.h2":"4. Síntesis","g.synth.ou":"Pestaña «Síntesis»","g.synth.p1":"Una lectura de conjunto que conecta tus tres pilares: <strong>Sol × Ascendente × camino de vida</strong>, con la combinación de tus <strong>elementos</strong> dominantes (fuego, tierra, aire, agua) y el hilo conductor de tu personalidad.","g.profils.h2":"5. Mis perfiles","g.profils.ou":"Inicio → mosaico «Mis perfiles» 👪","g.profils.p1":"Guarda a las personas y los animales de tu entorno:","g.profils.li1":"<strong>Añadir una persona</strong>: nombre, tipo de relación (pareja, hijo/a, padre/madre, hermano/a, amigo/a, compañero/a…), fecha, hora y lugar de nacimiento, y una <strong>foto</strong>.","g.profils.li2":"<strong>Editar</strong> (✎) o <strong>eliminar</strong> (🗑) un perfil en cualquier momento.","g.profils.li3":"Toca a una persona para ver su <strong>ficha completa</strong>: signo, ascendente, camino de vida y sus números, y accede después a vuestra compatibilidad.","g.compat.h2":"6. Compatibilidad","g.compat.ou":"Inicio → «Compatibilidad», o desde un perfil","g.compat.p1":"Compara tu carta con la de un ser querido en <strong>8 dimensiones</strong> puntuadas, con barras de progreso: amor, pasión, amistad, comunicación, trabajo, valores, día a día, estabilidad, además de tus <strong>fortalezas</strong> y tus <strong>puntos de atención</strong>. La lista de tus seres queridos está <strong>ordenada por puntuación</strong> en «Mis perfiles».","g.animaux.h2":"7. Animales de la familia","g.animaux.ou":"«Mis perfiles» → Añadir un animal, o mosaico Animales 🐾","g.animaux.p1":"¡La numerología también funciona para tus compañeros! Guarda un animal (nombre, especie, fecha, foto) y tócalo para ver su <strong>ficha numerológica</strong>: su número, su carácter y un consejo. (No hay horóscopo para los animales: con la numerología basta.)","g.bio.h2":"8. Biorritmos","g.bio.ou":"Inicio → mosaico «Biorritmos» 📈","g.bio.p1":"Tus tres ciclos del día — <strong>físico</strong> (23 d), <strong>emocional</strong> (28 d), <strong>intelectual</strong> (33 d) — contados desde tu nacimiento, con los <strong>días críticos</strong> y una curva de los próximos días.","g.prev.h2":"9. Previsiones y calendario","g.prev.ou":"Inicio → mosaicos «Previsiones» 📅 y «Calendario»","g.prev.li1":"<strong>Previsiones</strong>: la vibración de cada uno de tus próximos 12 meses y su número de días propicios.","g.prev.li2":"<strong>Calendario</strong>: la cuadrícula del mes con cada día coloreado (propicio, descanso, número maestro).","g.ciel.h2":"10. El cielo del momento","g.ciel.ou":"Inicio → mosaico «Cielo del momento» 🌌","g.ciel.p1":"Lo que ocurre hoy en el cielo: <strong>fase y signo de la Luna</strong>, período de <strong>Mercurio retrógrado</strong>, y el <strong>número universal</strong> del día, compartido por todos.","g.guid.h2":"11. Orientación y diario","g.guid.ou":"Pestaña «Orientación» · Diario en el inicio","g.guid.li1":"<strong>Orientación</strong>: responde a un breve cuestionario de vida y recibe una lectura personalizada, área por área (amor, trabajo, dinero, salud, espiritualidad) según tu año personal.","g.guid.li2":"<strong>Diario</strong>: anota la resonancia de tus días (1 a 5). El mosaico <em>Tendencias</em> muestra la evolución en el tiempo.","g.carte.h2":"12. Carta del día y compartir","g.carte.ou":"Inicio → mosaico «Carta del día» 🎴","g.carte.p1":"Una bonita imagen de tu día (número del día, signo, luna) lista para compartir con tus seres queridos. Un botón <em>Compartir mi día</em> permite también compartir texto de forma rápida.","g.pdf.h2":"13. Informe PDF completo","g.pdf.ou":"Rueda de Ajustes ⚙︎ → «Informe completo (PDF)»","g.pdf.p1":"Exporta toda tu carta (numerología, astrología, síntesis, año personal) en un elegante documento PDF para guardar o compartir.","g.outils.h2":"14. Herramientas","g.outils.ou":"Inicio → mosaico «Herramientas» 🧰","g.outils.li1":"<strong>Fecha favorable</strong>: los mejores días por venir según una intención (emprender, amar, decidir…).","g.outils.li2":"<strong>Nombre / nombre de uso</strong>: prueba la vibración de un nombre o un seudónimo.","g.outils.li3":"<strong>Dirección / número</strong>: el número de un lugar o de un número.","g.decouvrir.h2":"15. Descubrir","g.decouvrir.ou":"Inicio → mosaico «Descubrir» 📖","g.decouvrir.p1":"Una sección pedagógica que explica de forma sencilla todo lo que calcula la app: los números, los ciclos, la tabla de inclusión, la astrología, la síntesis. Ideal para empezar.","g.widget.h2":"16. Widget de pantalla de inicio (Android)","g.widget.ou":"Pantalla de inicio del teléfono","g.widget.p1":"Coloca tu <strong>número del día</strong> directamente en la pantalla de inicio: mantén pulsada la pantalla de inicio → <strong>Widgets</strong> → <strong>Numerocoon</strong>, y luego arrastra el widget. Un toque lo abre en la app.","g.reglages.h2":"17. Ajustes","g.reglages.ou":"Rueda dentada ⚙︎ arriba a la derecha","g.reglages.li1":"<strong>Idioma</strong>: 9 idiomas (francés, inglés, alemán, italiano, portugués, español, sueco, noruego, finés).","g.reglages.li2":"<strong>Tamaño del texto</strong>: pequeño / normal / grande.","g.reglages.li3":"<strong>Recordatorio diario</strong>: una notificación a la hora que elijas.","g.reglages.li4":"<strong>Copia de seguridad y restauración</strong>: exporta tus datos a un archivo y restáuralos en otro dispositivo (todo permanece local).","g.maj.h2":"18. Actualizaciones","g.maj.ou":"Automático · Ajustes ⚙︎ → «Actualizaciones»","g.maj.p1":"Al iniciarse, la app comprueba si existe una versión más reciente y te propone descargarla. También puedes comprobarlo manualmente desde los Ajustes. Tus datos se conservan de una versión a otra.","g.conf.h2":"19. Privacidad","g.conf.ou":"—","g.conf.p1":"Numerocoon no recopila <strong>ningún dato</strong>: sin cuenta, sin publicidad, sin rastreador. Todo lo que introduces permanece en tu dispositivo. Más detalles en la <a href=\"privacy.html\">política de privacidad</a>.","g.conf.astuce":"Numerocoon ofrece un apoyo de introspección y bienestar basado en tradiciones simbólicas. No es una predicción, ni un consejo médico, financiero o jurídico.","g.footer.line":"<strong>Numerocoon</strong> — de Bengacoon · <a href=\"index.html\">Inicio</a> · <a href=\"privacy.html\">Privacidad</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Política de privacidad — Numerocoon","priv.hero.title":"Política de privacidad","priv.hero.date":"Última actualización: 1 de septiembre de 2026 · Editor: Bengacoon","priv.summary":"<strong>En resumen:</strong> Numerocoon no recopila, no transmite ni comparte\n    <strong>ningún dato personal</strong>. No hay cuenta en línea, ni publicidad, ni rastreador,\n    ni herramienta de medición de audiencia. Todo lo que introduces permanece <strong>únicamente en tu\n    dispositivo</strong>. La única conexión a Internet sirve para comprobar si existe una actualización de\n    la aplicación — <em>no se envía ninguna información sobre ti</em>.","priv.s1.h2":"1. Quiénes somos","priv.s1.p1":"Numerocoon es una aplicación de numerología y horóscopo de bienestar, editada en el marco\n  del universo Bengacoon. Consultas: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Datos que recopilamos","priv.s2.p1":"<strong>Ninguno.</strong> No recopilamos ningún dato personal. La aplicación no crea\n  ninguna cuenta en un servidor, no te identifica, y no contiene publicidad, ni rastreador, ni\n  herramienta de análisis.","priv.s3.h2":"3. Datos guardados en tu dispositivo","priv.s3.intro":"Para funcionar, la aplicación guarda cierta información localmente, únicamente en tu\n  teléfono (nunca en un servidor):","priv.s3.li1":"tu perfil: nombre, apellido y correo electrónico eventuales;","priv.s3.li2":"tus datos de nacimiento: fecha, hora y lugar (para la carta y el ascendente);","priv.s3.li3":"los seres queridos y animales que guardas (nombre, datos de nacimiento, foto);","priv.s3.li4":"tus respuestas al cuestionario de orientación y las notas de tu diario;","priv.s3.li5":"tus preferencias: idioma, tamaño del texto, hora del recordatorio diario.","priv.s3.outro":"Estos datos nunca salen de tu dispositivo y nunca se nos transmiten.","priv.s4.h2":"4. Permisos y acceso a la red","priv.s4.li1":"<strong>Notificaciones</strong>: únicamente para el recordatorio diario que actives.","priv.s4.li2":"<strong>Fotos</strong>: únicamente si añades una foto a un perfil; la imagen permanece en tu dispositivo.","priv.s4.li3":"<strong>Internet</strong>: únicamente para <strong>comprobar la existencia de una actualización</strong>. <strong>No se envía ningún dato sobre ti.</strong>","priv.s4.p1":"La aplicación no solicita acceso a la ubicación, a los contactos, al micrófono ni a la cámara.\n  El lugar de nacimiento se elige de una lista integrada.","priv.s5.h2":"5. Compartir con terceros","priv.s5.p1":"Ninguno. La función de compartir («Compartir mi día», carta del día, copia de seguridad, PDF) utiliza el sistema de compartir\n  de tu dispositivo: el contenido solo se transmite a la aplicación que <em>tú</em> elijas. La\n  comprobación de actualizaciones contacta con GitHub, que técnicamente puede registrar la dirección IP\n  que origina la solicitud; nosotros no tenemos acceso a ella.","priv.s6.h2":"6. Conservación y eliminación","priv.s6.p1":"Tus datos permanecen en tu dispositivo tanto tiempo como desees. Puedes exportarlos,\n  restaurarlos, borrarlos desde los Ajustes, o eliminarlo todo desinstalando la aplicación.","priv.s7.h2":"7. Menores","priv.s7.p1":"La aplicación no se dirige especialmente a los menores y no recopila ningún dato que les\n  concierna.","priv.s8.h2":"8. Aviso de bienestar","priv.s8.p1":"Numerocoon ofrece un apoyo de introspección y bienestar basado en tradiciones\n  simbólicas. No es una predicción, ni un dispositivo médico, ni un consejo financiero o\n  jurídico.","priv.footer":"<strong>Numerocoon</strong> — de Bengacoon · <a href=\"index.html\">Inicio</a> ·\n    <a href=\"guide.html\">Guía</a> · © 2026 Bengacoon<br>\n    Contacto: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Tema e idioma","idx.ver.v210.desc":"Elige la apariencia: fondo claro u oscuro, o según tu teléfono. Y la interfaz ahora está totalmente traducida, hasta los ajustes."},"sv":{"idx.meta.title":"Numerocoon — Numerologi & välmåendehoroskop","idx.meta.desc":"Numerocoon, av Bengacoon: ditt detaljerade numerologiska diagram, din ascendent beräknad utifrån födelsetiden, horoskop, kompatibilitet och vägledning. Gratis, på 9 språk.","brand.by":"av Bengacoon","nav.home":"Hem","nav.features":"Funktioner","nav.guide":"Guide","nav.privacy":"Integritet","idx.hero.lead":"Numerologi & horoskop samlade. Utifrån ditt födelsedatum, din födelsetid och din födelseort upptäcker du ditt diagram, din ascendent och en vägledning som liknar dig.","idx.store.android":"<small>Android · direkt APK</small>Ladda ner","idx.store.play":"<small>Snart på</small>Google&nbsp;Play","idx.store.ios":"<small>Snart på</small>App&nbsp;Store","idx.func.eyebrow":"Vad appen gör","idx.func.h2":"Ett komplett porträtt, med mildhet","idx.func.sub":"Förstå dina tal, läs din himmel och gå framåt dag för dag — utan konto, utan facktermer.","idx.card.numero.h3":"Detaljerad numerologi","idx.card.numero.p":"Livsväg, uttryck, själ, personlighet, utmaningar och cykler, inklusionstabell och karmiska skulder. Ända till skuggsidan av varje tal, för ett ärligt porträtt.","idx.card.ascendant.h3":"Ascendent & horoskop","idx.card.ascendant.p":"Ditt soltecken och din ascendent, astronomiskt beräknad utifrån födelsetid och födelseort. Horoskop för dagen, veckan och gynnsamma dagar.","idx.card.synthese.h3":"Sammanfattning","idx.card.synthese.p":"En läsning som binder samman allt: Sol × Ascendent × livsväg, och kombinationen av dina dominerande element — eld, jord, luft, vatten.","idx.card.compat.h3":"Detaljerad kompatibilitet","idx.card.compat.p":"Spara dina närstående och jämför era diagram över 8 betygsatta dimensioner — kärlek, passion, vänskap, kommunikation, arbete, värderingar, vardag, stabilitet — med styrkor och punkter att vara uppmärksam på.","idx.card.guidance.h3":"Vägledning & dagbok","idx.card.guidance.p":"Ett livsformulär, och sedan en personlig vägledning område för område utifrån ditt personliga år. En dagbok för att notera hur dina dagar resonerar.","idx.card.rappel.h3":"Påminnelse & delning","idx.card.rappel.p":"En daglig påminnelse vid en tidpunkt du väljer så att du inte missar något, och delning av din dag med en enda rörelse, när du vill.","idx.free.price":"100 % gratis","idx.free.h2":"Allt bjuds på, utan reklam","idx.free.sub":"Inga köp, inga prenumerationer, inga låsta funktioner.","idx.free.li1":"Fullständigt numerologiskt diagram","idx.free.li2":"Ascendent, horoskop och gynnsamma dagar","idx.free.li3":"Sammanfattning, kompatibilitet och vägledning","idx.free.li4":"Dagbok, påminnelser och delning","idx.free.note":"Numerocoon är en gåva från Bengacoon-galaxen — att upptäcka helt fritt.","idx.lang.eyebrow":"För alla","idx.lang.h2":"Tillgänglig på 9 språk","idx.lang.sub":"Appen är helt översatt, ända ner till vägledningstexterna.","idx.ver.eyebrow":"Alltid i rörelse","idx.ver.h2":"De senaste versionerna","idx.ver.sub":"Numerocoon utvecklas regelbundet — här är de senaste nyheterna. Hela historiken finns på GitHub.","idx.ver.v1.label":"Djurprofil","idx.ver.v1.desc":"Ett djurs profil är mycket mer komplett: styrkor, behov, plats i familjen, ett kärleksfullt ord och dagens energi.","idx.ver.v2.label":"Ikon & guide","idx.ver.v2.desc":"Ny ikon (guldmedaljong, månskära) och en komplett inbyggd användarguide, tillgänglig offline.","idx.ver.v3.label":"Profiler & foton","idx.ver.v3.desc":"Ett foto på varje profil, en persons kompletta profil (tecken, ascendent, tal) och djurens numerologiska profil.","idx.ver.v4.label":"Profiler & djur","idx.ver.v4.desc":"Hantera flera profiler (partner, barn, familj…) med tillägg/redigering/borttagning och kompatibilitetslista, plus profiler för dina djur.","idx.ver.v5.label":"Kalender & himmel","idx.ver.v5.desc":"Månadens numerologiska kalender, ”ögonblickets himmel” (Månen, Merkurius retrograd, universellt tal) och ditt husdjurs numerologi.","idx.ver.v6.label":"Hemskärmswidget","idx.ver.v6.desc":"En Android-widget för att placera dagens tal direkt på telefonens hemskärm.","idx.ver.v7.label":"Kort, hjul & prognoser","idx.ver.v7.desc":"Dagens kort att dela, diagramhjul (Sol + Ascendent), prognoser över 12 månader, dagbokstrender, säkerhetskopiering/återställning, justerbar textstorlek och välkomstrundtur.","idx.ver.v8.label":"Direkta uppdateringar","idx.ver.v8.desc":"Den direkta APK-versionen laddar nu ner och installerar sina uppdateringar från appen, utan att gå via webbläsaren.","idx.ver.v9.label":"Biorytmer & PDF","idx.ver.v9.desc":"Dagens biorytmer (fysisk, emotionell, intellektuell), avsnittet ”Upptäck” för att förstå allt, och export av det kompletta diagrammet till PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Anpassning av iOS- och Android-versionerna och förberedelse för publicering på båda plattformarna.","idx.ver.v11.label":"Inställningar &amp; varumärke","idx.ver.v11.desc":"Kugghjul för åtkomst till Inställningar och signaturen ”av Bengacoon” på startsidan.","idx.ver.v12.label":"100 % översatt","idx.ver.v12.desc":"Fullständig lokalisering, ända ner till de sammansatta meningarna, på alla 9 språk.","idx.ver.more":"Se hela versionshistoriken →","idx.priv.eyebrow":"Dina data, hos dig","idx.priv.h2":"Ingenting lämnar din telefon","idx.priv.sub":"Inget konto att skapa, inga personuppgifter samlas in. Din profil och dina närstående stannar på din enhet. Den enda anslutningen används för att kontrollera uppdateringar — utan att skicka något som rör dig.","idx.footer":"<strong>Numerocoon</strong> — av Bengacoon · Tillgänglig på 9 språk<br>\n    <a href=\"guide.html\">Användarguide</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Integritetspolicy</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon erbjuder ett stöd för introspektion och välmående grundat på symboliska traditioner (numerologi, astrologi). Det är varken en förutsägelse, en medicinsk produkt, ett finansiellt eller juridiskt råd, och det ersätter inte rådgivning från en kvalificerad yrkesperson.</p>","g.meta.title":"Användarguide — Numerocoon","g.meta.desc":"Den kompletta guiden till Numerocoon: allt du kan göra (numerologi, ascendent, horoskop, kompatibilitet, profiler, biorytmer…) och hur.","g.hero.h1":"Användarguide","g.hero.p":"Allt du kan göra med Numerocoon, och hur. Appen finns på 9 språk; denna guide är på svenska.","g.toc.title":"Innehåll","g.toc.1":"1. Kom igång","g.toc.2":"2. Numerologi","g.toc.3":"3. Astrologi","g.toc.4":"4. Sammanfattning","g.toc.5":"5. Mina profiler","g.toc.6":"6. Kompatibilitet","g.toc.7":"7. Djur","g.toc.8":"8. Biorytmer","g.toc.9":"9. Prognoser & kalender","g.toc.10":"10. Ögonblickets himmel","g.toc.11":"11. Vägledning & dagbok","g.toc.12":"12. Kort & delning","g.toc.13":"13. PDF-rapport","g.toc.14":"14. Verktyg","g.toc.15":"15. Upptäck","g.toc.16":"16. Widget","g.toc.17":"17. Inställningar","g.toc.18":"18. Uppdateringar","g.toc.19":"19. Integritet","g.intro.note":"Varje avsnitt anger <strong style=\"color:var(--amethyste)\">var du hittar den</strong> i appen (fliken längst ner, kugghjulet för Inställningar uppe till höger, eller snabbåtkomstrutorna på startsidan).","g.demarrer.h2":"1. Kom igång — skapa din profil","g.demarrer.ou":"Vid första öppningen","g.demarrer.p1":"Vid start ber Numerocoon dig att skapa din profil. Fyll i:","g.demarrer.li1":"<strong>Förnamn</strong> (obligatoriskt), efternamn och e-post valfritt;","g.demarrer.li2":"<strong>Födelsedatum</strong> (dag, månad, år);","g.demarrer.li3":"<strong>Födelsetid</strong> och <strong>ort</strong> — nödvändiga för att beräkna din <em>ascendent</em> (valfria, men rekommenderade).","g.demarrer.astuce":"🔒 Allt stannar på din enhet: inget onlinekonto, inga data skickas. En välkomstrundtur presenterar appen vid första starten.","g.num.h2":"2. Numerologi","g.num.ou":"Fliken ”Numerologi”","g.num.p1":"Ditt kompletta pythagoreiska numerologiska diagram:","g.num.li1":"<strong>Livsväg</strong>: ditt huvudtal, med dess porträtt (styrkor, utmaningar, i kärleken, i arbetet, råd).","g.num.li2":"<strong>Skuggsida</strong>: ditt tals dolda sida och dess bekräftelse.","g.num.li3":"<strong>Namnets tal</strong>: uttryck, själ, personlighet, aktiv, ärftlig, födelsetal.","g.num.li4":"<strong>Inklusionstabell</strong>: dina tillgångar och dina läxor utifrån ditt namn.","g.num.li5":"<strong>Karmiska skulder</strong> (13, 14, 16, 19), <strong>utmaningar</strong> och <strong>livscykler</strong>.","g.num.li6":"<strong>Personligt år</strong>: temat för ditt pågående år.","g.astro.h2":"3. Astrologi & horoskop","g.astro.ou":"Fliken ”Horoskop”","g.astro.li1":"<strong>Soltecken</strong> och <strong>ascendent</strong> (astronomiskt beräknad utifrån din födelsetid och födelseort).","g.astro.li2":"<strong>Dagens horoskop</strong> och <strong>veckans</strong>, per område.","g.astro.li3":"<strong>Gynnsamma dagar</strong> under månaden.","g.astro.li4":"Snabb <strong>kompatibilitet</strong> mellan tecken.","g.astro.p1":"För <strong>ditt diagramhjul</strong> (dina 12 tecken i cirkel med Sol och Ascendent), använd rutan <em>Diagramhjul</em> på startsidan.","g.synth.h2":"4. Sammanfattning","g.synth.ou":"Fliken ”Sammanfattning”","g.synth.p1":"En helhetsläsning som binder samman dina tre pelare: <strong>Sol × Ascendent × livsväg</strong>, med kombinationen av dina dominerande <strong>element</strong> (eld, jord, luft, vatten) och den röda tråden i din personlighet.","g.profils.h2":"5. Mina profiler","g.profils.ou":"Startsida → rutan ”Mina profiler” 👪","g.profils.p1":"Spara människorna och djuren i din omgivning:","g.profils.li1":"<strong>Lägg till en person</strong>: förnamn, typ av relation (partner, barn, förälder, syskon, vän, kollega…), datum, tid och födelseort, och ett <strong>foto</strong>.","g.profils.li2":"<strong>Redigera</strong> (✎) eller <strong>ta bort</strong> (🗑) en profil när som helst.","g.profils.li3":"Tryck på en person för att se dess <strong>kompletta profil</strong>: tecken, ascendent, livsväg och dess tal — och gå sedan till er kompatibilitet.","g.compat.h2":"6. Kompatibilitet","g.compat.ou":"Startsida → ”Kompatibilitet”, eller från en profil","g.compat.p1":"Jämför ditt diagram med en närståendes över <strong>8 betygsatta dimensioner</strong>, med förloppsindikatorer: kärlek, passion, vänskap, kommunikation, arbete, värderingar, vardag, stabilitet — plus era <strong>styrkor</strong> och era <strong>punkter att vara uppmärksam på</strong>. Listan över dina närstående är <strong>sorterad efter poäng</strong> i ”Mina profiler”.","g.animaux.h2":"7. Familjens djur","g.animaux.ou":"”Mina profiler” → Lägg till ett djur, eller rutan Djur 🐾","g.animaux.p1":"Numerologin fungerar även för dina följeslagare! Spara ett djur (namn, art, datum, foto) och tryck på det för att se dess <strong>numerologiska profil</strong>: dess tal, dess karaktär och ett råd. (Inget horoskop för djur: numerologin räcker.)","g.bio.h2":"8. Biorytmer","g.bio.ou":"Startsida → rutan ”Biorytmer” 📈","g.bio.p1":"Dina tre cykler för dagen — <strong>fysisk</strong> (23 d), <strong>emotionell</strong> (28 d), <strong>intellektuell</strong> (33 d) — räknade från din födelse, med <strong>kritiska dagar</strong> och en kurva över de kommande dagarna.","g.prev.h2":"9. Prognoser & kalender","g.prev.ou":"Startsida → rutorna ”Prognoser” 📅 och ”Kalender”","g.prev.li1":"<strong>Prognoser</strong>: vibrationen för var och en av dina 12 kommande månader och dess antal gynnsamma dagar.","g.prev.li2":"<strong>Kalender</strong>: månadens rutnät med varje dag färglagd (gynnsam, vila, mästartal).","g.ciel.h2":"10. Ögonblickets himmel","g.ciel.ou":"Startsida → rutan ”Ögonblickets himmel” 🌌","g.ciel.p1":"Vad som händer på himlen idag: <strong>Månens fas och tecken</strong>, period av <strong>Merkurius retrograd</strong>, och dagens <strong>universella tal</strong>, delat av alla.","g.guid.h2":"11. Vägledning & dagbok","g.guid.ou":"Fliken ”Vägledning” · Dagbok på startsidan","g.guid.li1":"<strong>Vägledning</strong>: svara på ett kort livsformulär och få en personlig läsning, område för område (kärlek, arbete, pengar, hälsa, andlighet) utifrån ditt personliga år.","g.guid.li2":"<strong>Dagbok</strong>: notera hur dina dagar resonerar (1 till 5). Rutan <em>Trender</em> visar utvecklingen över tid.","g.carte.h2":"12. Dagens kort & delning","g.carte.ou":"Startsida → rutan ”Dagens kort” 🎴","g.carte.p1":"En vacker bild av din dag (dagens tal, tecken, måne) redo att delas med dina närstående. En knapp <em>Dela min dag</em> möjliggör också en snabb textdelning.","g.pdf.h2":"13. Komplett PDF-rapport","g.pdf.ou":"Kugghjulet för Inställningar ⚙︎ → ”Komplett rapport (PDF)”","g.pdf.p1":"Exportera hela ditt diagram (numerologi, astrologi, sammanfattning, personligt år) i ett elegant PDF-dokument att behålla eller dela.","g.outils.h2":"14. Verktyg","g.outils.ou":"Startsida → rutan ”Verktyg” 🧰","g.outils.li1":"<strong>Gynnsamt datum</strong>: de bästa kommande dagarna utifrån en avsikt (starta, älska, besluta…).","g.outils.li2":"<strong>Förnamn / använt namn</strong>: testa vibrationen hos ett förnamn eller en pseudonym.","g.outils.li3":"<strong>Adress / nummer</strong>: talet för en plats eller ett nummer.","g.decouvrir.h2":"15. Upptäck","g.decouvrir.ou":"Startsida → rutan ”Upptäck” 📖","g.decouvrir.p1":"Ett pedagogiskt avsnitt som enkelt förklarar allt appen beräknar: talen, cyklerna, inklusionstabellen, astrologin, sammanfattningen. Perfekt för nybörjare.","g.widget.h2":"16. Hemskärmswidget (Android)","g.widget.ou":"Telefonens hemskärm","g.widget.p1":"Placera ditt <strong>dagens tal</strong> direkt på hemskärmen: håll intryckt på hemskärmen → <strong>Widgetar</strong> → <strong>Numerocoon</strong>, och dra sedan widgeten. En tryckning öppnar den i appen.","g.reglages.h2":"17. Inställningar","g.reglages.ou":"Kugghjulet ⚙︎ uppe till höger","g.reglages.li1":"<strong>Språk</strong>: 9 språk (franska, engelska, tyska, italienska, portugisiska, spanska, svenska, norska, finska).","g.reglages.li2":"<strong>Textstorlek</strong>: liten / normal / stor.","g.reglages.li3":"<strong>Daglig påminnelse</strong>: en avisering vid en tidpunkt du väljer.","g.reglages.li4":"<strong>Säkerhetskopiering & återställning</strong>: exportera dina data till en fil och återställ dem på en annan enhet (allt stannar lokalt).","g.maj.h2":"18. Uppdateringar","g.maj.ou":"Automatiskt · Inställningar ⚙︎ → ”Uppdateringar”","g.maj.p1":"Vid start kontrollerar appen om det finns en nyare version och erbjuder dig att ladda ner den. Du kan också kontrollera manuellt från Inställningar. Dina data bevaras från en version till en annan.","g.conf.h2":"19. Integritet","g.conf.ou":"—","g.conf.p1":"Numerocoon samlar in <strong>inga data</strong>: inget konto, ingen reklam, ingen spårare. Allt du matar in stannar på din enhet. Detaljer i <a href=\"privacy.html\">integritetspolicyn</a>.","g.conf.astuce":"Numerocoon erbjuder ett stöd för introspektion och välmående grundat på symboliska traditioner. Det är varken en förutsägelse eller ett medicinskt, finansiellt eller juridiskt råd.","g.footer.line":"<strong>Numerocoon</strong> — av Bengacoon · <a href=\"index.html\">Hem</a> · <a href=\"privacy.html\">Integritet</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Integritetspolicy — Numerocoon","priv.hero.title":"Integritetspolicy","priv.hero.date":"Senast uppdaterad: 1 september 2026 · Utgivare: Bengacoon","priv.summary":"<strong>Sammanfattningsvis:</strong> Numerocoon samlar inte in, överför eller delar\n    <strong>några personuppgifter</strong>. Det finns varken onlinekonto, reklam, spårare\n    eller verktyg för besöksmätning. Allt du matar in stannar <strong>enbart på din\n    enhet</strong>. Den enda internetanslutningen används för att kontrollera om det finns en uppdatering av\n    appen — <em>ingen information som rör dig skickas</em>.","priv.s1.h2":"1. Vilka vi är","priv.s1.p1":"Numerocoon är en app för numerologi och välmåendehoroskop, utgiven inom ramen\n  för Bengacoon-universumet. Frågor: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Data vi samlar in","priv.s2.p1":"<strong>Inga.</strong> Vi samlar inte in några personuppgifter. Appen skapar\n  inget konto på en server, identifierar dig inte, och innehåller varken reklam, spårare eller\n  analysverktyg.","priv.s3.h2":"3. Data som lagras på din enhet","priv.s3.intro":"För att fungera lagrar appen viss information lokalt, enbart på din\n  telefon (aldrig på en server):","priv.s3.li1":"din profil: eventuellt förnamn, efternamn och e-post;","priv.s3.li2":"dina födelsedata: datum, tid och ort (för diagrammet och ascendenten);","priv.s3.li3":"de närstående och djur du sparar (namn, födelsedata, foto);","priv.s3.li4":"dina svar på vägledningsformuläret och anteckningarna i din dagbok;","priv.s3.li5":"dina inställningar: språk, textstorlek, tid för daglig påminnelse.","priv.s3.outro":"Dessa data lämnar aldrig din enhet och överförs aldrig till oss.","priv.s4.h2":"4. Behörigheter och nätverksåtkomst","priv.s4.li1":"<strong>Aviseringar</strong>: enbart för den dagliga påminnelse du aktiverar.","priv.s4.li2":"<strong>Foton</strong>: enbart om du lägger till ett foto på en profil; bilden stannar på din enhet.","priv.s4.li3":"<strong>Internet</strong>: enbart för att <strong>kontrollera om det finns en uppdatering</strong>. <strong>Ingen information som rör dig skickas.</strong>","priv.s4.p1":"Appen begär inte åtkomst till plats, kontakter, mikrofon eller kamera.\n  Födelseorten väljs från en inbyggd lista.","priv.s5.h2":"5. Delning med tredje part","priv.s5.p1":"Ingen. Delningen (”Dela min dag”, dagens kort, säkerhetskopiering, PDF) använder delningen\n  i ditt system: innehållet överförs endast till den app som <em>du</em> väljer. Kontrollen\n  av uppdateringar kontaktar GitHub, som tekniskt sett kan registrera IP-adressen som\n  förfrågan kommer från; vi har inte tillgång till den.","priv.s6.h2":"6. Lagring och radering","priv.s6.p1":"Dina data stannar på din enhet så länge du vill. Du kan exportera dem,\n  återställa dem, radera dem från Inställningar, eller ta bort allt genom att avinstallera appen.","priv.s7.h2":"7. Barn","priv.s7.p1":"Appen riktar sig inte särskilt till barn och samlar inte in några data som\n  rör dem.","priv.s8.h2":"8. Välmåendeinformation","priv.s8.p1":"Numerocoon erbjuder ett stöd för introspektion och välmående grundat på symboliska\n  traditioner. Det är varken en förutsägelse, en medicinsk produkt eller ett finansiellt eller\n  juridiskt råd.","priv.footer":"<strong>Numerocoon</strong> — av Bengacoon · <a href=\"index.html\">Hem</a> ·\n    <a href=\"guide.html\">Guide</a> · © 2026 Bengacoon<br>\n    Kontakt: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Tema och språk","idx.ver.v210.desc":"Välj utseende: ljus eller mörk bakgrund, eller enligt din telefon. Och gränssnittet är nu helt översatt, ända ner till inställningarna."},"no":{"idx.meta.title":"Numerocoon — Numerologi og velværehoroskop","idx.meta.desc":"Numerocoon, av Bengacoon: ditt detaljerte numerologiske kart, ditt ascendanttegn beregnet fra fødselstidspunktet, horoskop, kompatibilitet og veiledning. Gratis, på 9 språk.","brand.by":"av Bengacoon","nav.home":"Hjem","nav.features":"Funksjoner","nav.guide":"Guide","nav.privacy":"Personvern","idx.hero.lead":"Numerologi og horoskop samlet. Ut fra fødselsdato, fødselstidspunkt og fødested oppdager du kartet ditt, ascendanten din og en veiledning som ligner deg.","idx.store.android":"<small>Android · direkte APK</small>Last ned","idx.store.play":"<small>Snart på</small>Google&nbsp;Play","idx.store.ios":"<small>Snart på</small>App&nbsp;Store","idx.func.eyebrow":"Hva appen gjør","idx.func.h2":"Et komplett portrett, på en mild måte","idx.func.sub":"Forstå tallene dine, les himmelen din og gå videre dag for dag — uten konto, uten fagsjargong.","idx.card.numero.h3":"Detaljert numerologi","idx.card.numero.p":"Livsvei, uttrykk, sjel, personlighet, utfordringer og sykluser, inklusjonsdiagram og karmiske gjeld. Helt ned til skyggesiden av hvert tall, for et ærlig portrett.","idx.card.ascendant.h3":"Ascendant og horoskop","idx.card.ascendant.p":"Soltegnet ditt og ascendanten din, astronomisk beregnet fra fødselstidspunkt og fødested. Horoskop for dagen, uken og gunstige dager.","idx.card.synthese.h3":"Syntese","idx.card.synthese.p":"En tolkning som knytter alt sammen: Sol × Ascendant × livsvei, og kombinasjonen av dine dominerende elementer — ild, jord, luft, vann.","idx.card.compat.h3":"Detaljert kompatibilitet","idx.card.compat.p":"Lagre dine nærmeste og sammenlign kartene deres på 8 vurderte dimensjoner — kjærlighet, lidenskap, vennskap, kommunikasjon, arbeid, verdier, hverdag, stabilitet — med styrker og oppmerksomhetspunkter.","idx.card.guidance.h3":"Veiledning og dagbok","idx.card.guidance.p":"Et livsspørreskjema, og deretter en personlig veiledning område for område etter ditt personlige år. En dagbok for å notere gjenklangen i dagene dine.","idx.card.rappel.h3":"Påminnelse og deling","idx.card.rappel.p":"En daglig påminnelse på tidspunktet du velger, så du ikke går glipp av noe, og deling av dagen din med én bevegelse, når du ønsker det.","idx.free.price":"100 % gratis","idx.free.h2":"Alt er gratis, uten reklame","idx.free.sub":"Ingen kjøp, ingen abonnement, ingen låste funksjoner.","idx.free.li1":"Komplett numerologisk kart","idx.free.li2":"Ascendant, horoskop og gunstige dager","idx.free.li3":"Syntese, kompatibilitet og veiledning","idx.free.li4":"Dagbok, påminnelser og deling","idx.free.note":"Numerocoon er en gave fra Bengacoon-galaksen — å oppdage i full frihet.","idx.lang.eyebrow":"For alle","idx.lang.h2":"Tilgjengelig på 9 språk","idx.lang.sub":"Appen er fullstendig oversatt, helt ned til veiledningstekstene.","idx.ver.eyebrow":"Alltid i bevegelse","idx.ver.h2":"De nyeste versjonene","idx.ver.sub":"Numerocoon utvikler seg jevnlig — her er de nyeste nyhetene. Hele historikken finnes på GitHub.","idx.ver.v1.label":"Dyrekort","idx.ver.v1.desc":"Kortet til et dyr er langt mer utfyllende: styrker, behov, plass i familien, en kjærlig hilsen og dagens energi.","idx.ver.v2.label":"Ikon og guide","idx.ver.v2.desc":"Nytt ikon (gullmedaljong, månesigd) og en komplett innebygd bruksanvisning, tilgjengelig frakoblet.","idx.ver.v3.label":"Kort og bilder","idx.ver.v3.desc":"Et bilde på hver profil, det komplette kortet til en person (tegn, ascendant, tall) og det numerologiske kortet til dyrene.","idx.ver.v4.label":"Profiler og dyr","idx.ver.v4.desc":"Administrer flere profiler (partner, barn, familie …) med legg til / rediger / slett og en kompatibilitetsliste, samt profiler for dyrene dine.","idx.ver.v5.label":"Kalender og himmel","idx.ver.v5.desc":"Numerologisk kalender for måneden, «himmelen akkurat nå» (Månen, Merkur retrograd, universelt tall) og numerologien til kjæledyret ditt.","idx.ver.v6.label":"Hjem-widget","idx.ver.v6.desc":"En Android-widget som lar deg legge dagens tall rett på telefonens hjemskjerm.","idx.ver.v7.label":"Kort, hjul og prognoser","idx.ver.v7.desc":"Dagens kort til deling, kart-hjul (Sol + Ascendant), prognoser over 12 måneder, dagboktrender, sikkerhetskopiering/gjenoppretting, justerbar tekststørrelse og velkomstomvisning.","idx.ver.v8.label":"Direkte oppdateringer","idx.ver.v8.desc":"Direkte-APK-versjonen laster nå ned og installerer oppdateringene sine fra appen, uten å gå via nettleseren.","idx.ver.v9.label":"Biorytmer og PDF","idx.ver.v9.desc":"Dagens biorytmer (fysisk, emosjonell, intellektuell), «Oppdag»-seksjonen for å forstå alt, og eksport av det komplette kartet i PDF.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"Samkjøring av iOS- og Android-versjonene og forberedelse til publisering på begge plattformer.","idx.ver.v11.label":"Innstillinger og merkevare","idx.ver.v11.desc":"Tannhjul for tilgang til Innstillinger og signaturen «av Bengacoon» på hjemskjermen.","idx.ver.v12.label":"100 % oversatt","idx.ver.v12.desc":"Fullstendig lokalisering, helt ned til de sammensatte setningene, på alle de 9 språkene.","idx.ver.more":"Se hele versjonshistorikken →","idx.priv.eyebrow":"Dine data, hos deg","idx.priv.h2":"Ingenting forlater telefonen din","idx.priv.sub":"Ingen konto å opprette, ingen personopplysninger samles inn. Profilen din og dine nærmeste blir værende på enheten din. Den eneste tilkoblingen brukes til å sjekke etter oppdateringer — uten å sende noe om deg.","idx.footer":"<strong>Numerocoon</strong> — av Bengacoon · Tilgjengelig på 9 språk<br>\n    <a href=\"guide.html\">Bruksanvisning</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Personvernerklæring</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon tilbyr en støtte for selvrefleksjon og velvære basert på symbolske tradisjoner (numerologi, astrologi). Det er verken en spådom, et medisinsk hjelpemiddel eller finansielle eller juridiske råd, og det erstatter ikke rådene fra en kvalifisert fagperson.</p>","g.meta.title":"Bruksanvisning — Numerocoon","g.meta.desc":"Den komplette guiden til Numerocoon: alt du kan gjøre (numerologi, ascendant, horoskop, kompatibilitet, profiler, biorytmer …) og hvordan.","g.hero.h1":"Bruksanvisning","g.hero.p":"Alt du kan gjøre med Numerocoon, og hvordan. Appen finnes på 9 språk; denne guiden er på norsk.","g.toc.title":"Innhold","g.toc.1":"1. Kom i gang","g.toc.2":"2. Numerologi","g.toc.3":"3. Astrologi","g.toc.4":"4. Syntese","g.toc.5":"5. Mine profiler","g.toc.6":"6. Kompatibilitet","g.toc.7":"7. Dyr","g.toc.8":"8. Biorytmer","g.toc.9":"9. Prognoser og kalender","g.toc.10":"10. Himmelen akkurat nå","g.toc.11":"11. Veiledning og dagbok","g.toc.12":"12. Kort og deling","g.toc.13":"13. PDF-rapport","g.toc.14":"14. Verktøy","g.toc.15":"15. Oppdag","g.toc.16":"16. Widget","g.toc.17":"17. Innstillinger","g.toc.18":"18. Oppdateringer","g.toc.19":"19. Personvern","g.intro.note":"Hver seksjon angir <strong style=\"color:var(--amethyste)\">hvor du finner den</strong> i appen (fane nederst, tannhjulet for Innstillinger øverst til høyre, eller hurtigfliser på hjemskjermen).","g.demarrer.h2":"1. Kom i gang — opprett profilen din","g.demarrer.ou":"Ved første åpning","g.demarrer.p1":"Ved oppstart ber Numerocoon deg om å opprette profilen din. Fyll inn:","g.demarrer.li1":"<strong>Fornavn</strong> (obligatorisk), etternavn og e-post valgfritt;","g.demarrer.li2":"<strong>Fødselsdato</strong> (dag, måned, år);","g.demarrer.li3":"<strong>Fødselstidspunkt</strong> og <strong>fødested</strong> — nødvendig for å beregne <em>ascendanten</em> din (valgfritt, men anbefalt).","g.demarrer.astuce":"🔒 Alt blir værende på enheten din: ingen nettkonto, ingen data sendes. En velkomstomvisning presenterer appen ved første oppstart.","g.num.h2":"2. Numerologi","g.num.ou":"Fanen «Numerologi»","g.num.p1":"Ditt komplette pytagoreiske numerologiske kart:","g.num.li1":"<strong>Livsvei</strong>: hovedtallet ditt, med portrettet sitt (styrker, utfordringer, i kjærlighet, i arbeid, råd).","g.num.li2":"<strong>Skyggeside</strong>: den skjulte siden av tallet ditt og bekreftelsen som hører til.","g.num.li3":"<strong>Navnetall</strong>: uttrykk, sjel, personlighet, aktiv, arvet, fødselstall.","g.num.li4":"<strong>Inklusjonsdiagram</strong>: dine fortrinn og dine leksjoner ut fra navnet ditt.","g.num.li5":"<strong>Karmiske gjeld</strong> (13, 14, 16, 19), <strong>utfordringer</strong> og <strong>livssykluser</strong>.","g.num.li6":"<strong>Personlig år</strong>: temaet for ditt inneværende år.","g.astro.h2":"3. Astrologi og horoskop","g.astro.ou":"Fanen «Horoskop»","g.astro.li1":"<strong>Soltegn</strong> og <strong>ascendant</strong> (astronomisk beregnet fra fødselstidspunkt og fødested).","g.astro.li2":"<strong>Horoskop for dagen</strong> og for <strong>uken</strong>, etter livsområde.","g.astro.li3":"<strong>Gunstige dager</strong> i måneden.","g.astro.li4":"Rask <strong>kompatibilitet</strong> mellom tegn.","g.astro.p1":"For <strong>kart-hjulet ditt</strong> (dine 12 tegn i sirkel med Sol og Ascendant), bruk flisen <em>Kart-hjul</em> på hjemskjermen.","g.synth.h2":"4. Syntese","g.synth.ou":"Fanen «Syntese»","g.synth.p1":"En helhetlig tolkning som knytter sammen dine tre bærebjelker: <strong>Sol × Ascendant × livsvei</strong>, med kombinasjonen av dine dominerende <strong>elementer</strong> (ild, jord, luft, vann) og den røde tråden i personligheten din.","g.profils.h2":"5. Mine profiler","g.profils.ou":"Hjem → flisen «Mine profiler» 👪","g.profils.p1":"Lagre menneskene og dyrene rundt deg:","g.profils.li1":"<strong>Legg til en person</strong>: fornavn, type relasjon (partner, barn, forelder, søsken, venn, kollega …), fødselsdato, fødselstidspunkt og fødested, og et <strong>bilde</strong>.","g.profils.li2":"<strong>Rediger</strong> (✎) eller <strong>slett</strong> (🗑) en profil når som helst.","g.profils.li3":"Trykk på en person for å se det <strong>komplette kortet</strong>: tegn, ascendant, livsvei og tallene deres — og gå deretter til kompatibiliteten din.","g.compat.h2":"6. Kompatibilitet","g.compat.ou":"Hjem → «Kompatibilitet», eller fra en profil","g.compat.p1":"Sammenlign kartet ditt med en nærståendes på <strong>8 vurderte dimensjoner</strong>, med fremdriftslinjer: kjærlighet, lidenskap, vennskap, kommunikasjon, arbeid, verdier, hverdag, stabilitet — pluss dine <strong>styrker</strong> og dine <strong>oppmerksomhetspunkter</strong>. Listen over dine nærmeste er <strong>rangert etter poengsum</strong> i «Mine profiler».","g.animaux.h2":"7. Familiens dyr","g.animaux.ou":"«Mine profiler» → Legg til et dyr, eller flisen Dyr 🐾","g.animaux.p1":"Numerologi fungerer også for følgesvennene dine! Lagre et dyr (navn, art, fødselsdato, bilde) og trykk på det for å se det <strong>numerologiske kortet</strong>: tallet, karakteren og et råd. (Ingen horoskop for dyr: numerologien holder.)","g.bio.h2":"8. Biorytmer","g.bio.ou":"Hjem → flisen «Biorytmer» 📈","g.bio.p1":"Dine tre dagssykluser — <strong>fysisk</strong> (23 d), <strong>emosjonell</strong> (28 d), <strong>intellektuell</strong> (33 d) — talt fra fødselen din, med de <strong>kritiske dagene</strong> og en kurve over de nærmeste dagene.","g.prev.h2":"9. Prognoser og kalender","g.prev.ou":"Hjem → flisene «Prognoser» 📅 og «Kalender»","g.prev.li1":"<strong>Prognoser</strong>: vibrasjonen for hver av dine 12 kommende måneder og antallet gunstige dager.","g.prev.li2":"<strong>Kalender</strong>: rutenettet for måneden med hver dag fargelagt (gunstig, hvile, mestertall).","g.ciel.h2":"10. Himmelen akkurat nå","g.ciel.ou":"Hjem → flisen «Himmelen akkurat nå» 🌌","g.ciel.p1":"Hva som skjer på himmelen i dag: <strong>månefase og -tegn</strong>, periode med <strong>Merkur retrograd</strong>, og dagens <strong>universelle tall</strong>, delt av alle.","g.guid.h2":"11. Veiledning og dagbok","g.guid.ou":"Fanen «Veiledning» · Dagbok på hjemskjermen","g.guid.li1":"<strong>Veiledning</strong>: svar på et kort livsspørreskjema og motta en personlig tolkning, område for område (kjærlighet, arbeid, penger, helse, spiritualitet) etter ditt personlige år.","g.guid.li2":"<strong>Dagbok</strong>: noter gjenklangen i dagene dine (1 til 5). Flisen <em>Trender</em> viser utviklingen over tid.","g.carte.h2":"12. Dagens kort og deling","g.carte.ou":"Hjem → flisen «Dagens kort» 🎴","g.carte.p1":"Et vakkert bilde av dagen din (dagens tall, tegn, måne) klart til å deles med dine nærmeste. En <em>Del dagen min</em>-knapp gir også rask tekstdeling.","g.pdf.h2":"13. Komplett PDF-rapport","g.pdf.ou":"Tannhjulet ⚙︎ → «Komplett rapport (PDF)»","g.pdf.p1":"Eksporter hele kartet ditt (numerologi, astrologi, syntese, personlig år) i et elegant PDF-dokument til å beholde eller dele.","g.outils.h2":"14. Verktøy","g.outils.ou":"Hjem → flisen «Verktøy» 🧰","g.outils.li1":"<strong>Gunstig dato</strong>: de beste dagene fremover ut fra en intensjon (starte, elske, bestemme …).","g.outils.li2":"<strong>Fornavn / brukernavn</strong>: test vibrasjonen til et fornavn eller et pseudonym.","g.outils.li3":"<strong>Adresse / nummer</strong>: tallet til et sted eller et nummer.","g.decouvrir.h2":"15. Oppdag","g.decouvrir.ou":"Hjem → flisen «Oppdag» 📖","g.decouvrir.p1":"En pedagogisk seksjon som enkelt forklarer alt appen beregner: tallene, syklusene, inklusjonsdiagrammet, astrologien, syntesen. Perfekt for å komme i gang.","g.widget.h2":"16. Widget på hjemskjermen (Android)","g.widget.ou":"Telefonens hjemskjerm","g.widget.p1":"Legg <strong>dagens tall</strong> rett på hjemskjermen: hold inne på hjemskjermen → <strong>Widgeter</strong> → <strong>Numerocoon</strong>, og dra deretter widgeten. Ett trykk åpner den i appen.","g.reglages.h2":"17. Innstillinger","g.reglages.ou":"Tannhjulet ⚙︎ øverst til høyre","g.reglages.li1":"<strong>Språk</strong>: 9 språk (fransk, engelsk, tysk, italiensk, portugisisk, spansk, svensk, norsk, finsk).","g.reglages.li2":"<strong>Tekststørrelse</strong>: liten / normal / stor.","g.reglages.li3":"<strong>Daglig påminnelse</strong>: et varsel på tidspunktet du velger.","g.reglages.li4":"<strong>Sikkerhetskopiering og gjenoppretting</strong>: eksporter dataene dine til en fil og gjenopprett dem på en annen enhet (alt forblir lokalt).","g.maj.h2":"18. Oppdateringer","g.maj.ou":"Automatisk · Innstillinger ⚙︎ → «Oppdateringer»","g.maj.p1":"Ved oppstart sjekker appen om det finnes en nyere versjon og tilbyr å laste den ned. Du kan også sjekke manuelt fra Innstillinger. Dataene dine bevares fra en versjon til den neste.","g.conf.h2":"19. Personvern","g.conf.ou":"—","g.conf.p1":"Numerocoon samler inn <strong>ingen data</strong>: ingen konto, ingen reklame, ingen sporing. Alt du legger inn blir værende på enheten din. Detaljer i <a href=\"privacy.html\">personvernerklæringen</a>.","g.conf.astuce":"Numerocoon tilbyr en støtte for selvrefleksjon og velvære basert på symbolske tradisjoner. Det er verken en spådom eller medisinske, finansielle eller juridiske råd.","g.footer.line":"<strong>Numerocoon</strong> — av Bengacoon · <a href=\"index.html\">Hjem</a> · <a href=\"privacy.html\">Personvern</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Personvernerklæring — Numerocoon","priv.hero.title":"Personvernerklæring","priv.hero.date":"Sist oppdatert: 1. september 2026 · Utgiver: Bengacoon","priv.summary":"<strong>Kort oppsummert:</strong> Numerocoon samler inn, overfører og deler\n    <strong>ingen personopplysninger</strong>. Det finnes verken nettkonto, reklame, sporing\n    eller verktøy for målgruppemåling. Alt du legger inn blir værende <strong>utelukkende på\n    enheten din</strong>. Den eneste tilkoblingen til Internett brukes til å sjekke om det finnes en oppdatering av\n    appen — <em>ingen informasjon om deg sendes</em>.","priv.s1.h2":"1. Hvem vi er","priv.s1.p1":"Numerocoon er en app for numerologi og velværehoroskop, utgitt som en del\n  av Bengacoon-universet. Spørsmål: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Data vi samler inn","priv.s2.p1":"<strong>Ingen.</strong> Vi samler ikke inn noen personopplysninger. Appen oppretter\n  ingen konto på en server, identifiserer deg ikke, og inneholder verken reklame, sporing eller\n  analyseverktøy.","priv.s3.h2":"3. Data lagret på enheten din","priv.s3.intro":"For å fungere lagrer appen visse opplysninger lokalt, kun på\n  telefonen din (aldri på en server):","priv.s3.li1":"profilen din: fornavn, eventuelt etternavn og e-post;","priv.s3.li2":"fødselsdataene dine: dato, tidspunkt og sted (for kartet og ascendanten);","priv.s3.li3":"de nærstående og dyrene du lagrer (navn, fødselsdata, bilde);","priv.s3.li4":"svarene dine på veiledningsspørreskjemaet og notatene i dagboken din;","priv.s3.li5":"innstillingene dine: språk, tekststørrelse, tidspunkt for daglig påminnelse.","priv.s3.outro":"Disse dataene forlater aldri enheten din og overføres aldri til oss.","priv.s4.h2":"4. Tillatelser og nettverkstilgang","priv.s4.li1":"<strong>Varsler</strong>: kun for den daglige påminnelsen du aktiverer.","priv.s4.li2":"<strong>Bilder</strong>: kun hvis du legger et bilde til en profil; bildet blir værende på enheten din.","priv.s4.li3":"<strong>Internett</strong>: kun for å <strong>sjekke om det finnes en oppdatering</strong>. <strong>Ingen data om deg sendes.</strong>","priv.s4.p1":"Appen ber ikke om tilgang til posisjon, kontakter, mikrofon eller kamera.\n  Fødestedet velges fra en innebygd liste.","priv.s5.h2":"5. Deling med tredjeparter","priv.s5.p1":"Ingen. Delingen («Del dagen min», dagens kort, sikkerhetskopi, PDF) bruker delingsfunksjonen\n  i systemet ditt: innholdet overføres kun til appen <em>du</em> velger. Sjekk\n  av oppdatering kontakter GitHub, som teknisk sett kan registrere IP-adressen\n  forespørselen kommer fra; vi har ikke tilgang til den.","priv.s6.h2":"6. Oppbevaring og sletting","priv.s6.p1":"Dataene dine blir værende på enheten din så lenge du ønsker. Du kan eksportere dem,\n  gjenopprette dem, slette dem fra Innstillinger, eller fjerne alt ved å avinstallere appen.","priv.s7.h2":"7. Barn","priv.s7.p1":"Appen henvender seg ikke særskilt til barn og samler ikke inn noen data om\n  dem.","priv.s8.h2":"8. Velværeforbehold","priv.s8.p1":"Numerocoon tilbyr en støtte for selvrefleksjon og velvære basert på symbolske\n  tradisjoner. Det er verken en spådom, et medisinsk hjelpemiddel eller finansielle eller\n  juridiske råd.","priv.footer":"<strong>Numerocoon</strong> — av Bengacoon · <a href=\"index.html\">Hjem</a> ·\n    <a href=\"guide.html\">Guide</a> · © 2026 Bengacoon<br>\n    Kontakt: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Tema og språk","idx.ver.v210.desc":"Velg utseende: lys eller mørk bakgrunn, eller etter telefonen din. Og grensesnittet er nå fullstendig oversatt, helt ned til innstillingene."},"fi":{"idx.meta.title":"Numerocoon — Numerologia & hyvinvointihoroskooppi","idx.meta.desc":"Numerocoon, Bengacoonilta: yksityiskohtainen numerologinen kartta, syntymäajasta laskettu nousumerkki, horoskooppi, yhteensopivuus ja opastus. Ilmainen, 9 kielellä.","brand.by":"Bengacoonilta","nav.home":"Etusivu","nav.features":"Toiminnot","nav.guide":"Opas","nav.privacy":"Tietosuoja","idx.hero.lead":"Numerologia ja horoskooppi yhdessä. Syntymäpäiväsi, -aikasi ja -paikkasi perusteella löydät kartan, nousumerkkisi ja opastuksen, joka on juuri sinun näköisesi.","idx.store.android":"<small>Android · suora APK</small>Lataa","idx.store.play":"<small>Pian saatavilla</small>Google&nbsp;Play","idx.store.ios":"<small>Pian saatavilla</small>App&nbsp;Store","idx.func.eyebrow":"Mitä sovellus tekee","idx.func.h2":"Kattava muotokuva, lempeästi","idx.func.sub":"Ymmärrä lukusi, lue taivaasi ja etene päivä kerrallaan — ilman tiliä, ilman ammattislangia.","idx.card.numero.h3":"Yksityiskohtainen numerologia","idx.card.numero.p":"Elämänpolku, ilmaisu, sielu, persoonallisuus, haasteet ja jaksot, inkluusioruudukko ja karmalliset velat. Aina jokaisen luvun varjopuoleen asti, rehellistä muotokuvaa varten.","idx.card.ascendant.h3":"Nousumerkki & horoskooppi","idx.card.ascendant.p":"Aurinkomerkkisi ja nousumerkkisi, laskettuna astronomisesti syntymäajasta ja -paikasta. Päivän, viikon ja suotuisten päivien horoskooppi.","idx.card.synthese.h3":"Yhteenveto","idx.card.synthese.p":"Luenta, joka yhdistää kaiken: Aurinko × Nousumerkki × elämänpolku ja hallitsevien elementtiesi yhdistelmä — tuli, maa, ilma, vesi.","idx.card.compat.h3":"Yksityiskohtainen yhteensopivuus","idx.card.compat.p":"Tallenna läheisesi ja vertaa karttojanne kahdeksassa arvioidussa ulottuvuudessa — rakkaus, intohimo, ystävyys, viestintä, työ, arvot, arki, vakaus — vahvuuksineen ja huomionkohtineen.","idx.card.guidance.h3":"Opastus & päiväkirja","idx.card.guidance.p":"Elämänkysely ja sen jälkeen henkilökohtainen opastus alue alueelta henkilökohtaisen vuotesi mukaan. Päiväkirja päiviesi tunnelman muistiin merkitsemiseksi.","idx.card.rappel.h3":"Muistutus & jakaminen","idx.card.rappel.p":"Päivittäinen muistutus valitsemaasi aikaan, jottet menetä mitään, ja päiväsi jakaminen yhdellä eleellä silloin, kun haluat.","idx.free.price":"100 % ilmainen","idx.free.h2":"Kaikki tarjotaan, ilman mainoksia","idx.free.sub":"Ei ostoksia, ei tilauksia, ei lukittuja toimintoja.","idx.free.li1":"Täydellinen numerologinen kartta","idx.free.li2":"Nousumerkki, horoskooppi ja suotuisat päivät","idx.free.li3":"Yhteenveto, yhteensopivuus ja opastus","idx.free.li4":"Päiväkirja, muistutukset ja jakaminen","idx.free.note":"Numerocoon on lahja Bengacoon-galaksilta — vapaasti tutkittavaksi.","idx.lang.eyebrow":"Kaikille","idx.lang.h2":"Saatavilla 9 kielellä","idx.lang.sub":"Sovellus on käännetty kokonaan, aina opastusteksteihin asti.","idx.ver.eyebrow":"Aina liikkeessä","idx.ver.h2":"Uusimmat versiot","idx.ver.sub":"Numerocoon kehittyy säännöllisesti — tässä viimeaikaiset uutuudet. Koko historia on GitHubissa.","idx.ver.v1.label":"Eläinkortti","idx.ver.v1.desc":"Eläimen kortti on paljon kattavampi: vahvuudet, tarpeet, paikka perheessä, hellä sana ja päivän energia.","idx.ver.v2.label":"Kuvake & opas","idx.ver.v2.desc":"Uusi kuvake (kultainen medaljonki, kuunsirppi) ja täydellinen käyttöopas sisäänrakennettuna, käytettävissä myös offline-tilassa.","idx.ver.v3.label":"Kortit & valokuvat","idx.ver.v3.desc":"Valokuva jokaiseen profiiliin, henkilön täydellinen kortti (merkki, nousumerkki, luvut) ja eläinten numerologinen kortti.","idx.ver.v4.label":"Profiilit & eläimet","idx.ver.v4.desc":"Hallitse useita profiileja (puoliso, lapset, perhe…) lisäyksellä/muokkauksella/poistolla ja yhteensopivuuslistalla, sekä profiilit eläimillesi.","idx.ver.v5.label":"Kalenteri & taivas","idx.ver.v5.desc":"Kuukauden numerologinen kalenteri, ”hetken taivas” (Kuu, Merkurius retrogradissa, universaali luku) ja lemmikkisi numerologia.","idx.ver.v6.label":"Kotinäytön widget","idx.ver.v6.desc":"Android-widget, jolla asetat päivän lukusi suoraan puhelimesi kotinäytölle.","idx.ver.v7.label":"Kortti, kehä & ennusteet","idx.ver.v7.desc":"Jaettava päivän kortti, kartan kehä (Aurinko + Nousumerkki), 12 kuukauden ennusteet, päiväkirjan trendit, varmuuskopiointi/palautus, säädettävä tekstikoko ja tervetuloakierros.","idx.ver.v8.label":"Suorat päivitykset","idx.ver.v8.desc":"Suora APK-versio lataa ja asentaa päivityksensä nyt suoraan sovelluksesta, ilman selaimen kautta kulkemista.","idx.ver.v9.label":"Biorytmit & PDF","idx.ver.v9.desc":"Päivän biorytmit (fyysinen, emotionaalinen, älyllinen), ”Tutustu”-osio kaiken ymmärtämiseksi ja täydellisen kartan vienti PDF-muodossa.","idx.ver.v10.label":"iOS &amp; Android","idx.ver.v10.desc":"iOS- ja Android-versioiden yhdenmukaistaminen ja julkaisun valmistelu molemmilla alustoilla.","idx.ver.v11.label":"Asetukset &amp; brändi","idx.ver.v11.desc":"Hammasratas Asetuksiin pääsyä varten ja ”Bengacoonilta”-allekirjoitus etusivulla.","idx.ver.v12.label":"100 % käännetty","idx.ver.v12.desc":"Täydellinen lokalisointi, aina koottuihin lauseisiin asti, kaikilla 9 kielellä.","idx.ver.more":"Katso koko versiohistoria →","idx.priv.eyebrow":"Tietosi, sinun luonasi","idx.priv.h2":"Mikään ei lähde puhelimestasi","idx.priv.sub":"Ei tiliä luotavaksi, ei kerättyjä henkilötietoja. Profiilisi ja läheisesi pysyvät laitteessasi. Ainoa yhteys palvelee päivitysten tarkistamista — lähettämättä mitään sinua koskevaa.","idx.footer":"<strong>Numerocoon</strong> — Bengacoonilta · Saatavilla 9 kielellä<br>\n    <a href=\"guide.html\">Käyttöopas</a> &nbsp;·&nbsp; <a href=\"privacy.html\">Tietosuojakäytäntö</a> &nbsp;·&nbsp; © 2026 Bengacoon\n    <p class=\"disc\">Numerocoon tarjoaa itsetutkiskelun ja hyvinvoinnin tuen, joka perustuu symbolisiin perinteisiin (numerologia, astrologia). Se ei ole ennustus, lääkinnällinen laite eikä taloudellinen tai oikeudellinen neuvonta, eikä se korvaa pätevän ammattilaisen arviota.</p>","g.meta.title":"Käyttöopas — Numerocoon","g.meta.desc":"Numerocoonin täydellinen opas: kaikki mitä voit tehdä (numerologia, nousumerkki, horoskooppi, yhteensopivuus, profiilit, biorytmit…) ja miten.","g.hero.h1":"Käyttöopas","g.hero.p":"Kaikki mitä voit tehdä Numerocoonilla, ja miten. Sovellus on 9 kielellä; tämä opas on suomeksi.","g.toc.title":"Sisällys","g.toc.1":"1. Aloittaminen","g.toc.2":"2. Numerologia","g.toc.3":"3. Astrologia","g.toc.4":"4. Yhteenveto","g.toc.5":"5. Omat profiilit","g.toc.6":"6. Yhteensopivuus","g.toc.7":"7. Eläimet","g.toc.8":"8. Biorytmit","g.toc.9":"9. Ennusteet & kalenteri","g.toc.10":"10. Hetken taivas","g.toc.11":"11. Opastus & päiväkirja","g.toc.12":"12. Kortti & jakaminen","g.toc.13":"13. PDF-raportti","g.toc.14":"14. Työkalut","g.toc.15":"15. Tutustu","g.toc.16":"16. Widget","g.toc.17":"17. Asetukset","g.toc.18":"18. Päivitykset","g.toc.19":"19. Tietosuoja","g.intro.note":"Jokainen osio kertoo <strong style=\"color:var(--amethyste)\">mistä sen löytää</strong> sovelluksesta (välilehti alhaalla, Asetusten hammasratas oikeassa yläkulmassa tai etusivun pikakäyttöruudut).","g.demarrer.h2":"1. Aloittaminen — luo profiilisi","g.demarrer.ou":"Ensimmäisellä avauskerralla","g.demarrer.p1":"Käynnistyessään Numerocoon pyytää sinua luomaan profiilisi. Anna:","g.demarrer.li1":"<strong>Etunimi</strong> (pakollinen), sukunimi ja sähköposti valinnaisia;","g.demarrer.li2":"<strong>Syntymäaika</strong> (päivä, kuukausi, vuosi);","g.demarrer.li3":"<strong>Syntymäaika kellonaikana</strong> ja <strong>paikka</strong> — tarpeen <em>nousumerkkisi</em> laskemiseksi (valinnaisia, mutta suositeltavia).","g.demarrer.astuce":"🔒 Kaikki pysyy laitteessasi: ei verkkotiliä, ei lähetettyä tietoa. Tervetuloakierros esittelee sovelluksen ensimmäisellä käynnistyskerralla.","g.num.h2":"2. Numerologia","g.num.ou":"”Numerologia”-välilehti","g.num.p1":"Täydellinen pythagoralainen numerologinen karttasi:","g.num.li1":"<strong>Elämänpolku</strong>: pääluku muotokuvineen (vahvuudet, haasteet, rakkaudessa, työssä, neuvo).","g.num.li2":"<strong>Varjopuoli</strong>: lukusi kätketty puoli ja sen vahvistus.","g.num.li3":"<strong>Nimen luvut</strong>: ilmaisu, sielu, persoonallisuus, aktiivinen, perinnöllinen, syntymäluku.","g.num.li4":"<strong>Inkluusioruudukko</strong>: vahvuutesi ja oppiläksysi nimesi perusteella.","g.num.li5":"<strong>Karmalliset velat</strong> (13, 14, 16, 19), <strong>haasteet</strong> ja <strong>elämänjaksot</strong>.","g.num.li6":"<strong>Henkilökohtainen vuosi</strong>: kuluvan vuotesi teema.","g.astro.h2":"3. Astrologia & horoskooppi","g.astro.ou":"”Horoskooppi”-välilehti","g.astro.li1":"<strong>Aurinkomerkki</strong> ja <strong>nousumerkki</strong> (laskettu astronomisesti syntymäajastasi ja -paikastasi).","g.astro.li2":"<strong>Päivän</strong> ja <strong>viikon</strong> horoskooppi aloittain.","g.astro.li3":"Kuukauden <strong>suotuisat päivät</strong>.","g.astro.li4":"Nopea <strong>yhteensopivuus</strong> merkkien välillä.","g.astro.p1":"<strong>Karttasi kehää</strong> varten (12 merkkiäsi ympyrässä Auringon ja Nousumerkin kanssa) käytä etusivun <em>Kartan kehä</em> -ruutua.","g.synth.h2":"4. Yhteenveto","g.synth.ou":"”Yhteenveto”-välilehti","g.synth.p1":"Kokonaisluenta, joka yhdistää kolme pilariasi: <strong>Aurinko × Nousumerkki × elämänpolku</strong>, hallitsevien <strong>elementtiesi</strong> yhdistelmän (tuli, maa, ilma, vesi) ja persoonallisuutesi punaisen langan kanssa.","g.profils.h2":"5. Omat profiilit","g.profils.ou":"Etusivu → ”Omat profiilit” -ruutu 👪","g.profils.p1":"Tallenna ympäristösi ihmiset ja eläimet:","g.profils.li1":"<strong>Lisää henkilö</strong>: etunimi, suhteen tyyppi (puoliso, lapsi, vanhempi, sisarus, ystävä, kollega…), syntymäpäivä, -aika ja -paikka sekä <strong>valokuva</strong>.","g.profils.li2":"<strong>Muokkaa</strong> (✎) tai <strong>poista</strong> (🗑) profiili milloin tahansa.","g.profils.li3":"Kosketa henkilöä nähdäksesi hänen <strong>täydellisen korttinsa</strong>: merkki, nousumerkki, elämänpolku ja hänen lukunsa — ja siirry sitten yhteensopivuuteenne.","g.compat.h2":"6. Yhteensopivuus","g.compat.ou":"Etusivu → ”Yhteensopivuus” tai profiilista","g.compat.p1":"Vertaa karttaasi läheisen karttaan <strong>kahdeksassa</strong> arvioidussa ulottuvuudessa edistymispalkeilla: rakkaus, intohimo, ystävyys, viestintä, työ, arvot, arki, vakaus — sekä <strong>vahvuutenne</strong> ja <strong>huomionkohtanne</strong>. Läheistesi lista on <strong>järjestetty pistemäärän mukaan</strong> ”Omat profiilit” -kohdassa.","g.animaux.h2":"7. Perheen eläimet","g.animaux.ou":"”Omat profiilit” → Lisää eläin, tai Eläimet-ruutu 🐾","g.animaux.p1":"Numerologia toimii myös lemmikeillesi! Tallenna eläin (nimi, laji, syntymäpäivä, valokuva) ja kosketa sitä nähdäksesi sen <strong>numerologisen kortin</strong>: sen luvun, luonteen ja neuvon. (Ei horoskooppia eläimille: numerologia riittää.)","g.bio.h2":"8. Biorytmit","g.bio.ou":"Etusivu → ”Biorytmit”-ruutu 📈","g.bio.p1":"Kolme päivän jaksoasi — <strong>fyysinen</strong> (23 pv), <strong>emotionaalinen</strong> (28 pv), <strong>älyllinen</strong> (33 pv) — laskettuna syntymästäsi, <strong>kriittisine päivineen</strong> ja tulevien päivien käyrineen.","g.prev.h2":"9. Ennusteet & kalenteri","g.prev.ou":"Etusivu → ”Ennusteet” 📅 ja ”Kalenteri” -ruudut","g.prev.li1":"<strong>Ennusteet</strong>: kunkin 12 tulevan kuukautesi värähtely ja sen kantavien päivien määrä.","g.prev.li2":"<strong>Kalenteri</strong>: kuukauden ruudukko jokainen päivä väritettynä (kantava, lepo, mestariluku).","g.ciel.h2":"10. Hetken taivas","g.ciel.ou":"Etusivu → ”Hetken taivas” -ruutu 🌌","g.ciel.p1":"Mitä taivaalla tapahtuu tänään: <strong>Kuun vaihe ja merkki</strong>, <strong>Merkuriuksen retrogradin</strong> jakso ja päivän <strong>universaali luku</strong>, joka on kaikille yhteinen.","g.guid.h2":"11. Opastus & päiväkirja","g.guid.ou":"”Opastus”-välilehti · Päiväkirja etusivulla","g.guid.li1":"<strong>Opastus</strong>: vastaa lyhyeen elämänkyselyyn ja saat henkilökohtaisen luennan alue alueelta (rakkaus, työ, raha, terveys, henkisyys) henkilökohtaisen vuotesi mukaan.","g.guid.li2":"<strong>Päiväkirja</strong>: merkitse muistiin päiviesi tunnelma (1–5). <em>Trendit</em>-ruutu näyttää kehityksen ajan mittaan.","g.carte.h2":"12. Päivän kortti & jakaminen","g.carte.ou":"Etusivu → ”Päivän kortti” -ruutu 🎴","g.carte.p1":"Kaunis kuva päivästäsi (päivän luku, merkki, kuu) valmiina jaettavaksi läheistesi kanssa. <em>Jaa päiväni</em> -painike mahdollistaa myös nopean tekstijakamisen.","g.pdf.h2":"13. Täydellinen PDF-raportti","g.pdf.ou":"Asetusten hammasratas ⚙︎ → ”Täydellinen raportti (PDF)”","g.pdf.p1":"Vie koko karttasi (numerologia, astrologia, yhteenveto, henkilökohtainen vuosi) tyylikkääseen PDF-dokumenttiin säilytettäväksi tai jaettavaksi.","g.outils.h2":"14. Työkalut","g.outils.ou":"Etusivu → ”Työkalut”-ruutu 🧰","g.outils.li1":"<strong>Suotuisa päivä</strong>: parhaat tulevat päivät aikomuksen mukaan (aloittaa, rakastaa, päättää…).","g.outils.li2":"<strong>Etunimi / käyttönimi</strong>: testaa etunimen tai lempinimen värähtelyä.","g.outils.li3":"<strong>Osoite / numero</strong>: paikan tai numeron luku.","g.decouvrir.h2":"15. Tutustu","g.decouvrir.ou":"Etusivu → ”Tutustu”-ruutu 📖","g.decouvrir.p1":"Pedagoginen osio, joka selittää yksinkertaisesti kaiken mitä sovellus laskee: luvut, jaksot, inkluusioruudukon, astrologian, yhteenvedon. Ihanteellinen aloittelijoille.","g.widget.h2":"16. Kotinäytön widget (Android)","g.widget.ou":"Puhelimen kotinäyttö","g.widget.p1":"Aseta <strong>päivän lukusi</strong> suoraan kotinäytölle: pidä kotinäyttöä painettuna → <strong>Widgetit</strong> → <strong>Numerocoon</strong>, ja vedä sitten widget paikalleen. Painallus avaa sen sovelluksessa.","g.reglages.h2":"17. Asetukset","g.reglages.ou":"Hammasratas ⚙︎ oikeassa yläkulmassa","g.reglages.li1":"<strong>Kieli</strong>: 9 kieltä (ranska, englanti, saksa, italia, portugali, espanja, ruotsi, norja, suomi).","g.reglages.li2":"<strong>Tekstikoko</strong>: pieni / normaali / suuri.","g.reglages.li3":"<strong>Päivittäinen muistutus</strong>: ilmoitus valitsemaasi aikaan.","g.reglages.li4":"<strong>Varmuuskopiointi & palautus</strong>: vie tietosi tiedostoon ja palauta ne toisella laitteella (kaikki pysyy paikallisena).","g.maj.h2":"18. Päivitykset","g.maj.ou":"Automaattinen · Asetukset ⚙︎ → ”Päivitykset”","g.maj.p1":"Käynnistyessään sovellus tarkistaa, onko uudempaa versiota olemassa, ja ehdottaa sen lataamista. Voit myös tarkistaa manuaalisesti Asetuksista. Tietosi säilyvät versiosta toiseen.","g.conf.h2":"19. Tietosuoja","g.conf.ou":"—","g.conf.p1":"Numerocoon ei kerää <strong>mitään tietoja</strong>: ei tiliä, ei mainoksia, ei seuraimia. Kaikki syöttämäsi pysyy laitteessasi. Yksityiskohdat <a href=\"privacy.html\">tietosuojakäytännössä</a>.","g.conf.astuce":"Numerocoon tarjoaa itsetutkiskelun ja hyvinvoinnin tuen, joka perustuu symbolisiin perinteisiin. Se ei ole ennustus eikä lääkinnällinen, taloudellinen tai oikeudellinen neuvonta.","g.footer.line":"<strong>Numerocoon</strong> — Bengacoonilta · <a href=\"index.html\">Etusivu</a> · <a href=\"privacy.html\">Tietosuoja</a><br>\n    © 2026 Bengacoon","priv.meta.title":"Tietosuojakäytäntö — Numerocoon","priv.hero.title":"Tietosuojakäytäntö","priv.hero.date":"Viimeksi päivitetty: 1. syyskuuta 2026 · Julkaisija: Bengacoon","priv.summary":"<strong>Lyhyesti:</strong> Numerocoon ei kerää, välitä eikä jaa\n    <strong>mitään henkilötietoja</strong>. Ei ole verkkotiliä, mainoksia, seuraimia\n    eikä kävijämittausta. Kaikki syöttämäsi pysyy <strong>ainoastaan laitteessasi</strong>. Ainoa internetyhteys palvelee sovelluksen päivityksen tarkistamista — <em>mitään sinua koskevaa tietoa ei lähetetä</em>.","priv.s1.h2":"1. Keitä me olemme","priv.s1.p1":"Numerocoon on numerologian ja hyvinvointihoroskoopin sovellus, joka on julkaistu\n  Bengacoon-maailman puitteissa. Kysymykset: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>.","priv.s2.h2":"2. Tiedot, joita keräämme","priv.s2.p1":"<strong>Ei mitään.</strong> Emme kerää mitään henkilötietoja. Sovellus ei luo\n  mitään tiliä palvelimelle, ei tunnista sinua eikä sisällä mainoksia, seuraimia eikä\n  analyysityökaluja.","priv.s3.h2":"3. Laitteellesi tallennetut tiedot","priv.s3.intro":"Toimiakseen sovellus tallentaa tiettyjä tietoja paikallisesti, vain sinun\n  puhelimeesi (ei koskaan palvelimelle):","priv.s3.li1":"profiilisi: mahdollinen etunimi, sukunimi ja sähköposti;","priv.s3.li2":"syntymätietosi: päivä, kellonaika ja paikka (karttaa ja nousumerkkiä varten);","priv.s3.li3":"tallentamasi läheiset ja eläimet (nimi, syntymätiedot, valokuva);","priv.s3.li4":"vastauksesi opastuskyselyyn ja päiväkirjasi merkinnät;","priv.s3.li5":"asetuksesi: kieli, tekstikoko, päivittäisen muistutuksen aika.","priv.s3.outro":"Nämä tiedot eivät koskaan poistu laitteestasi eikä niitä koskaan välitetä meille.","priv.s4.h2":"4. Käyttöoikeudet ja verkkoyhteys","priv.s4.li1":"<strong>Ilmoitukset</strong>: vain aktivoimaasi päivittäistä muistutusta varten.","priv.s4.li2":"<strong>Valokuvat</strong>: vain jos lisäät valokuvan profiiliin; kuva pysyy laitteessasi.","priv.s4.li3":"<strong>Internet</strong>: vain <strong>päivityksen olemassaolon tarkistamiseksi</strong>. <strong>Mitään sinua koskevaa tietoa ei lähetetä.</strong>","priv.s4.p1":"Sovellus ei pyydä pääsyä sijaintiin, yhteystietoihin, mikrofoniin tai kameraan.\n  Syntymäpaikka valitaan sisäänrakennetusta listasta.","priv.s5.h2":"5. Jakaminen kolmansien osapuolten kanssa","priv.s5.p1":"Ei mitään. Jakaminen (”Jaa päiväni”, päivän kortti, varmuuskopiointi, PDF) käyttää järjestelmäsi\n  jakamista: sisältö välitetään vain siihen sovellukseen, jonka <em>sinä</em> valitset. Päivityksen\n  tarkistus ottaa yhteyttä GitHubiin, joka voi teknisesti tallentaa pyynnön lähtökohtana olevan\n  IP-osoitteen; meillä ei ole siihen pääsyä.","priv.s6.h2":"6. Säilytys ja poistaminen","priv.s6.p1":"Tietosi pysyvät laitteessasi niin kauan kuin haluat. Voit viedä ne,\n  palauttaa ne, poistaa ne Asetuksista tai poistaa kaiken poistamalla sovelluksen.","priv.s7.h2":"7. Lapset","priv.s7.p1":"Sovellusta ei ole suunnattu erityisesti lapsille eikä se kerää mitään heitä\n  koskevaa tietoa.","priv.s8.h2":"8. Hyvinvointia koskeva varoitus","priv.s8.p1":"Numerocoon tarjoaa itsetutkiskelun ja hyvinvoinnin tuen, joka perustuu symbolisiin\n  perinteisiin. Se ei ole ennustus, lääkinnällinen laite eikä taloudellinen tai\n  oikeudellinen neuvonta.","priv.footer":"<strong>Numerocoon</strong> — Bengacoonilta · <a href=\"index.html\">Etusivu</a> ·\n    <a href=\"guide.html\">Opas</a> · © 2026 Bengacoon<br>\n    Yhteystiedot: <a href=\"mailto:bengacoon74@gmail.com\">bengacoon74@gmail.com</a>","idx.ver.v210.label":"Teema ja kieli","idx.ver.v210.desc":"Valitse ulkoasu: vaalea tai tumma tausta, tai puhelimesi mukaan. Ja käyttöliittymä on nyt täysin käännetty, asetuksia myöten."}};

(function(){
  var LANGS=["fr","en","de","it","pt","es","sv","no","fi"];
  function pick(){
    try{var s=localStorage.getItem("numerocoon:lang"); if(s&&DICT[s])return s;}catch(e){}
    var n=(navigator.language||"fr").slice(0,2).toLowerCase();
    if(n==="nb"||n==="nn")n="no";
    return DICT[n]?n:"fr";
  }
  function apply(lang){
    var d=DICT[lang]||{}, fr=DICT.fr||{};
    document.documentElement.lang=lang;
    var nodes=document.querySelectorAll("[data-i18n]");
    for(var i=0;i<nodes.length;i++){
      var el=nodes[i], k=el.getAttribute("data-i18n");
      var v=(d[k]!==undefined?d[k]:fr[k]);
      if(v===undefined||v===null)continue;
      var attr=el.getAttribute("data-i18n-attr");
      if(attr)el.setAttribute(attr,v); else el.innerHTML=v;
    }
    var sel=document.getElementById("ncLang"); if(sel)sel.value=lang;
    try{localStorage.setItem("numerocoon:lang",lang);}catch(e){}
  }
  function init(){
    var sel=document.getElementById("ncLang");
    if(sel)sel.addEventListener("change",function(){apply(this.value);});
    apply(pick());
  }
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init); else init();
})();
